package com.banktemplates;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;

/**
 * Holds the state and operations for editing a {@link BankTemplate}'s layout - both from the side-panel
 * grid editor and live over the bank. You can build or rearrange a layout <b>without owning the items</b>:
 * added items render as faded placeholders, and dragging/inserting/removing slots just rewrites the
 * template's per-tab lists.
 * <p>
 * Edits are written through to disk on each change and a snapshot is kept so {@link #revert()} can undo
 * the whole session. Only user templates are editable (presets are read-only). Each mutation locks on
 * the template instance so the client-thread renderer never reads a half-applied change.
 */
@Slf4j
@Singleton
public class LayoutEditor
{
	// OSRS allows nine numbered bank tabs (plus the main/all-items view).
	static final int MAX_TABS = 9;

	private final TemplateManager templateManager;
	private final ItemManager itemManager;

	// volatile: read from the client thread (renderer/overlay) and the Swing thread (panel/editor).
	private volatile boolean editing;
	private volatile BankTemplate target;
	// A deep copy taken when editing starts, so the whole session can be reverted.
	private volatile BankTemplate snapshot;

	// Notified after any change (and on start/stop) so the panel editor and the bank view refresh.
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	@Inject
	LayoutEditor(TemplateManager templateManager, ItemManager itemManager)
	{
		this.templateManager = templateManager;
		this.itemManager = itemManager;
	}

	void addListener(Runnable r)
	{
		if (r != null)
		{
			listeners.add(r);
		}
	}

	void removeListener(Runnable r)
	{
		listeners.remove(r);
	}

	boolean isEditing()
	{
		return editing;
	}

	BankTemplate getTarget()
	{
		return target;
	}

	/**
	 * The template that bank edits write to: the explicit edit session's target if one is open, otherwise
	 * the active (applied) template. This is what makes editing "always on" while a template is applied -
	 * dragging/releasing in the bank adjusts whatever template you're currently looking at.
	 */
	BankTemplate liveTemplate()
	{
		final BankTemplate t = target;
		if (editing && t != null)
		{
			return t;
		}
		final BankTemplate active = templateManager.getActive();
		return active != null && !active.isPreset() ? active : null;
	}

	/**
	 * True when the live (editable) template is the one currently applied/rendered, so in-bank editing is
	 * valid. Editing a template from the side panel does NOT activate it, so its window edits don't render
	 * over the bank - in-bank editing stays off until that template is the active one.
	 */
	boolean liveOverBank()
	{
		final BankTemplate t = liveTemplate();
		final BankTemplate a = templateManager.getActive();
		return t != null && a != null && t.getName().equals(a.getName());
	}

	/** True when the bank should show {@code template} in editable form. */
	boolean isEditing(BankTemplate template)
	{
		final BankTemplate t = target;
		return editing && t != null && template != null && t.getName().equals(template.getName());
	}

	/**
	 * Begins editing a user template in the side-panel window. Does NOT activate it - the bank keeps showing
	 * whatever template is currently applied, so you can edit a template without changing your bank view.
	 * Snapshots it for {@link #revert()}. Presets and nulls are rejected.
	 */
	boolean start(BankTemplate template)
	{
		if (template == null || template.isPreset())
		{
			return false;
		}
		this.target = template;
		this.snapshot = template.copy();
		this.editing = true;
		notifyChanged();
		return true;
	}

	/** Ends the editing session, tidying trailing gaps left while arranging. */
	void finish()
	{
		final BankTemplate t = target;
		if (t != null)
		{
			synchronized (t)
			{
				for (int tab : t.definedTabs())
				{
					trimTrailing(t.editableTab(tab));
					t.pruneTab(tab);
				}
			}
			templateManager.saveUserTemplate(t);
		}
		editing = false;
		target = null;
		snapshot = null;
		notifyChanged();
	}

	/** Ends the session and DISCARDS changes, restoring the template to how it was when editing began
	 *  (used when the editor window is closed without applying). */
	void discard()
	{
		final BankTemplate t = target;
		final BankTemplate snap = snapshot;
		if (t != null && snap != null)
		{
			t.restoreTabsFrom(snap);
			templateManager.saveUserTemplate(t);
		}
		editing = false;
		target = null;
		snapshot = null;
		notifyChanged();
	}

	/** Restores the template to how it was when editing started, then keeps editing. */
	void revert()
	{
		final BankTemplate t = target;
		final BankTemplate snap = snapshot;
		if (t != null && snap != null)
		{
			t.restoreTabsFrom(snap);
			templateManager.saveUserTemplate(t);
			notifyChanged();
		}
	}

	// ---- Layout mutations (all no-ops unless this template is being edited) ------------------

	/** Appends an item (or a filler) to a tab. Real items are deduped silently; fillers can repeat. */
	void addItem(int tab, int itemId)
	{
		if (itemId == BankTemplate.FILLER || (itemId > 0 && !contains(itemId)))
		{
			edit(tab, slots -> addOrFill(slots, itemId));
		}
	}

	// Places an item in the first empty slot if there is one, else appends - so adding to a freshly created
	// tab (which starts as a row of empty slots) lands in the top-left, not in the row after the empties.
	private static void addOrFill(List<Integer> slots, int itemId)
	{
		for (int i = 0; i < slots.size(); i++)
		{
			final Integer v = slots.get(i);
			if (v == null || v == BankTemplate.EMPTY)
			{
				slots.set(i, itemId);
				return;
			}
		}
		slots.add(itemId);
	}

	/**
	 * Replaces the slot at {@code pos} in {@code tab} with a real item, or - if that item is already
	 * elsewhere in the layout - reports where via {@code onDup} (with a user-facing message) and changes
	 * nothing. Fillers replace unconditionally. Must run on the client thread (it reads the item name).
	 * {@code onDup} is invoked on the client thread.
	 */
	void replaceItemOrReport(int tab, int pos, int itemId, Consumer<String> onDup)
	{
		if (pos < 0)
		{
			return;
		}
		if (itemId == BankTemplate.FILLER)
		{
			setSlot(tab, pos, itemId);
			return;
		}
		if (itemId <= 0)
		{
			return;
		}
		final BankTemplate t = liveTemplate();
		if (t == null)
		{
			return;
		}
		final int[] loc = locate(t, itemId);
		// Picking the item that's already in this same slot is a no-op, not a duplicate.
		if (loc != null && !(loc[0] == tab && loc[1] == pos))
		{
			if (onDup != null)
			{
				onDup.accept(itemName(itemId) + " is already in " + describe(t, loc[0], loc[1]) + ".");
			}
			return;
		}
		setSlot(tab, pos, itemId);
	}

	// The {tab, index} of itemId in the template, or null if absent.
	private int[] locate(BankTemplate t, int itemId)
	{
		synchronized (t)
		{
			for (TabLayout tl : t.getTabs())
			{
				final List<Integer> layout = tl.getLayout();
				for (int i = 0; i < layout.size(); i++)
				{
					final Integer v = layout.get(i);
					if (v != null && v == itemId)
					{
						return new int[]{tl.getTab(), i};
					}
				}
			}
		}
		return null;
	}

	private String describe(BankTemplate t, int tab, int index)
	{
		final int cols = t.getColumns();
		final String tabName = tab == BankTemplate.MAIN_TAB ? "the Main tab" : "Tab " + tab;
		return tabName + ", row " + (index / cols + 1) + ", slot " + (index % cols + 1);
	}

	private String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (RuntimeException e)
		{
			return "That item";
		}
	}

	/** The [tab, pos] where {@code itemId} already sits in the layout, or null if it isn't present. Client thread. */
	int[] find(int itemId)
	{
		final BankTemplate t = liveTemplate();
		return t == null ? null : locate(t, itemId);
	}

	/** Display name for an item id (client thread - reads the item composition). */
	String displayName(int itemId)
	{
		return itemName(itemId);
	}

	/** "the Main tab" / "Tab N", for a tab number. */
	String tabLabel(int tab)
	{
		return tab == BankTemplate.MAIN_TAB ? "the Main tab" : "Tab " + tab;
	}

	/** True if the current edit session has changes that differ from the pre-edit snapshot. */
	boolean hasUnsavedChanges()
	{
		final BankTemplate t = target;
		final BankTemplate snap = snapshot;
		if (!editing || t == null || snap == null)
		{
			return false;
		}
		synchronized (t)
		{
			final List<Integer> tabs = t.definedTabs();
			if (!tabs.equals(snap.definedTabs()))
			{
				return true;
			}
			for (int tab : tabs)
			{
				if (!java.util.Arrays.equals(t.tabLayout(tab), snap.tabLayout(tab)))
				{
					return true;
				}
			}
			return false;
		}
	}

	/** True if {@code itemId} already appears anywhere in the template being edited. */
	boolean contains(int itemId)
	{
		final BankTemplate t = liveTemplate();
		if (t == null)
		{
			return false;
		}
		synchronized (t)
		{
			for (TabLayout tl : t.getTabs())
			{
				for (Integer v : tl.getLayout())
				{
					if (v != null && v == itemId)
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	/** Sets a slot to an item id, {@link BankTemplate#FILLER} or {@link BankTemplate#EMPTY}. */
	void setSlot(int tab, int pos, int value)
	{
		if (pos >= 0)
		{
			edit(tab, slots ->
			{
				while (slots.size() <= pos)
				{
					slots.add(BankTemplate.EMPTY);
				}
				slots.set(pos, value);
			});
		}
	}

	/** Removes a slot, shifting everything after it up; collapses the tab if it leaves no real items. */
	void removeSlot(int tab, int pos)
	{
		final BankTemplate t = liveTemplate();
		if (t == null)
		{
			return;
		}
		synchronized (t)
		{
			final List<Integer> slots = t.editableTab(tab);
			if (pos >= 0 && pos < slots.size())
			{
				slots.remove(pos);
			}
			if (tab != BankTemplate.MAIN_TAB && !hasRealItems(slots))
			{
				t.removeTab(tab);
			}
		}
		templateManager.saveUserTemplate(t);
		notifyChanged();
	}

	/** Inserts an empty slot at {@code pos}, shifting everything from there down. */
	void insertEmpty(int tab, int pos)
	{
		edit(tab, slots -> slots.add(Math.max(0, Math.min(pos, slots.size())), BankTemplate.EMPTY));
	}

	/**
	 * Moves the slot at {@code from} to {@code to}, shifting the slots in between (drag-to-insert). A
	 * {@code to} at or past the end appends.
	 */
	void moveSlot(int tab, int from, int to)
	{
		if (from == to)
		{
			return;
		}
		edit(tab, slots ->
		{
			if (from >= 0 && from < slots.size())
			{
				final Integer value = slots.remove(from);
				slots.add(Math.max(0, Math.min(to, slots.size())), value);
			}
		});
	}

	/**
	 * Moves the slot at {@code fromPos} in {@code fromTab} to the end of {@code toTab} (drag onto a tab).
	 * Returns the destination tab's final number (shifted down if collapsing the source renumbered it), or
	 * -1 if nothing moved - so the bank can follow the item when the viewed tab collapses.
	 */
	int moveToTab(int fromTab, int fromPos, int toTab)
	{
		final BankTemplate t = liveTemplate();
		if (t == null || fromTab == toTab)
		{
			return -1;
		}
		synchronized (t)
		{
			final List<Integer> from = t.editableTab(fromTab);
			if (fromPos < 0 || fromPos >= from.size())
			{
				return -1;
			}
			final Integer value = from.remove(fromPos);
			if (value != null && value != BankTemplate.EMPTY)
			{
				t.editableTab(toTab).add(value);
			}
			// Collapse the source tab if dragging its last item out left it with no real items; the
			// destination shifts down a number if it sat above the removed tab.
			if (fromTab != BankTemplate.MAIN_TAB && !hasRealItems(from))
			{
				t.removeTab(fromTab);
				if (toTab > fromTab)
				{
					toTab--;
				}
			}
		}
		templateManager.saveUserTemplate(t);
		notifyChanged();
		return toTab;
	}

	private static boolean hasRealItems(List<Integer> slots)
	{
		for (Integer v : slots)
		{
			if (v != null && v > 0 && v != BankTemplate.FILLER)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Moves the slot at {@code fromPos} in {@code fromTab} into a brand-new tab (the next free numbered
	 * tab), mirroring the game's "drag to the + tab" behaviour. Respects the 9-tab maximum. Returns the new
	 * tab's final number (so the bank can follow the item), or -1 if all nine tabs are already used.
	 */
	int moveToNewTab(int fromTab, int fromPos)
	{
		final BankTemplate t = liveTemplate();
		if (t == null)
		{
			return -1;
		}
		int next;
		synchronized (t)
		{
			int max = 0;
			for (int tab : t.definedTabs())
			{
				if (tab != BankTemplate.MAIN_TAB)
				{
					max = Math.max(max, tab);
				}
			}
			next = max + 1;
		}
		if (next > MAX_TABS)
		{
			return -1;
		}
		return moveToTab(fromTab, fromPos, next);
	}

	/**
	 * Reorders numbered tabs (drag a tab onto another to move it there), renumbering them 1..N. Returns the
	 * moved tab's new number, or -1 on a no-op.
	 */
	int moveTab(int fromTab, int toTab)
	{
		final BankTemplate t = liveTemplate();
		if (t == null)
		{
			return -1;
		}
		final int newNum = t.moveTab(fromTab, toTab);
		if (newNum > 0)
		{
			templateManager.saveUserTemplate(t);
			notifyChanged();
		}
		return newNum;
	}

	/** Swaps the contents of two slots (drag-to-swap). Pads with empties if needed. */
	void swapSlots(int tab, int a, int b)
	{
		if (a == b || a < 0 || b < 0)
		{
			return;
		}
		edit(tab, slots ->
		{
			while (slots.size() <= Math.max(a, b))
			{
				slots.add(BankTemplate.EMPTY);
			}
			final Integer tmp = slots.get(a);
			slots.set(a, slots.get(b));
			slots.set(b, tmp);
		});
	}

	/** Adds a full empty row (one tab's worth of columns) so there's room to drop items into. */
	void addRow(int tab)
	{
		final BankTemplate t = target;
		final int columns = t != null ? t.getColumns() : BankLayoutRenderer.ITEMS_PER_ROW;
		edit(tab, slots ->
		{
			for (int i = 0; i < columns; i++)
			{
				slots.add(BankTemplate.EMPTY);
			}
		});
	}

	/** Empties a tab. */
	void clearTab(int tab)
	{
		edit(tab, List::clear);
	}

	// Applies a mutation to a tab's slot list under the template lock, then saves and refreshes. A
	// no-op if editing has already stopped (so a late drag/drop can't touch a finished session).
	private void edit(int tab, java.util.function.Consumer<List<Integer>> op)
	{
		final BankTemplate t = liveTemplate();
		if (t == null)
		{
			return;
		}
		synchronized (t)
		{
			op.accept(t.editableTab(tab));
		}
		templateManager.saveUserTemplate(t);
		notifyChanged();
	}

	/** Sets (0 clears, reverting to the first item) the custom icon for a tab on the live template. */
	void setTabIcon(int tab, int iconId)
	{
		final BankTemplate t = liveTemplate();
		if (t == null || tab == BankTemplate.MAIN_TAB)
		{
			return;
		}
		synchronized (t)
		{
			t.setTabIcon(tab, iconId);
		}
		templateManager.saveUserTemplate(t);
		notifyChanged();
	}

	/** Collapses a tab into the all-items view: moves its real items to the main tab, then removes the tab. */
	void collapseTab(int tab)
	{
		final BankTemplate t = liveTemplate();
		if (t == null || tab == BankTemplate.MAIN_TAB)
		{
			return;
		}
		synchronized (t)
		{
			final List<Integer> main = t.editableTab(BankTemplate.MAIN_TAB);
			for (Integer v : t.copyTab(tab))
			{
				if (v != null && v > 0 && v != BankTemplate.FILLER)
				{
					main.add(v);
				}
			}
			t.removeTab(tab);
		}
		templateManager.saveUserTemplate(t);
		notifyChanged();
	}

	// Drop trailing empty slots from a tab so a saved layout doesn't carry dead space at the end.
	private static void trimTrailing(List<Integer> slots)
	{
		for (int i = slots.size() - 1; i >= 0; i--)
		{
			final Integer v = slots.get(i);
			if (v != null && v != BankTemplate.EMPTY)
			{
				break;
			}
			slots.remove(i);
		}
	}

	private void notifyChanged()
	{
		for (Runnable r : listeners)
		{
			try
			{
				r.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Layout editor listener failed", e);
			}
		}
	}
}

package com.banktemplates;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;

/**
 * Owns the set of templates (bundled presets + user-saved templates) and the currently active one.
 * Presets ship as a single JSON resource; user templates live as individual JSON files under
 * {@code .runelite/bank-templates/}. The active selection is persisted via {@link ConfigManager}.
 */
@Slf4j
@Singleton
public class TemplateManager
{
	private static final String PRESETS_RESOURCE = "/com/banktemplates/presets/presets.json";
	private static final Path STORAGE_DIR = RuneLite.RUNELITE_DIR.toPath().resolve("bank-templates");
	private static final Pattern UNSAFE_FILENAME = Pattern.compile("[^a-zA-Z0-9-_]");
	private static final Type TEMPLATE_LIST_TYPE = new TypeToken<List<BankTemplate>>()
	{
	}.getType();

	private final Gson gson;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;

	private final List<BankTemplate> presets = new ArrayList<>();
	// Keyed by template name; preserves insertion order for stable panel display.
	private final Map<String, BankTemplate> userTemplates = new LinkedHashMap<>();

	private BankTemplate active;

	@Inject
	TemplateManager(Gson gson, ConfigManager configManager, ScheduledExecutorService executor)
	{
		this.gson = gson;
		this.configManager = configManager;
		this.executor = executor;
	}

	void load()
	{
		loadPresets();
		loadUserTemplates();
		resolveActiveFromConfig();
	}

	private void loadPresets()
	{
		presets.clear();
		try (InputStream in = TemplateManager.class.getResourceAsStream(PRESETS_RESOURCE))
		{
			if (in == null)
			{
				log.debug("No bundled presets resource found at {}", PRESETS_RESOURCE);
				return;
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				final List<BankTemplate> loaded = gson.fromJson(reader, TEMPLATE_LIST_TYPE);
				if (loaded != null)
				{
					for (BankTemplate t : loaded)
					{
						if (t != null && t.getName() != null)
						{
							t.setPreset(true);
							presets.add(t);
						}
					}
				}
			}
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Failed to load bundled bank template presets", e);
		}
	}

	private void loadUserTemplates()
	{
		userTemplates.clear();
		if (!Files.isDirectory(STORAGE_DIR))
		{
			return;
		}

		try (Stream<Path> files = Files.list(STORAGE_DIR))
		{
			files.filter(p -> p.toString().toLowerCase(Locale.ROOT).endsWith(".json"))
				.sorted()
				.forEach(this::loadUserTemplateFile);
		}
		catch (IOException e)
		{
			log.warn("Failed to list bank template directory {}", STORAGE_DIR, e);
		}
	}

	private void loadUserTemplateFile(Path file)
	{
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			final BankTemplate t = gson.fromJson(reader, BankTemplate.class);
			// A blank name can't be created any more (saveUserTemplate rejects it), but older builds could
			// persist one, leaving an unusable nameless "ghost" card. Skip those - the name is this file's
			// storage key, so a blank-named file is unreachable anyway.
			if (t != null && t.getName() != null && !t.getName().trim().isEmpty() && !t.getTabs().isEmpty())
			{
				t.setPreset(false);
				t.pruneTrailingEmptyTabs();
				userTemplates.put(t.getName(), t);
			}
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Skipping unreadable bank template file {}", file, e);
		}
	}

	private void resolveActiveFromConfig()
	{
		final String name = configManager.getConfiguration(BankTemplatesConfig.GROUP, BankTemplatesConfig.ACTIVE_TEMPLATE_KEY);
		active = name == null || name.isEmpty() ? null : findByName(name);
	}

	/** All templates the user can choose from: presets first, then user templates. */
	public List<BankTemplate> getTemplates()
	{
		final List<BankTemplate> all = new ArrayList<>(presets);
		all.addAll(userTemplates.values());
		return all;
	}

	public List<BankTemplate> getPresets()
	{
		return Collections.unmodifiableList(presets);
	}

	public List<BankTemplate> getUserTemplates()
	{
		final List<BankTemplate> l = new ArrayList<>(userTemplates.values());
		l.sort(Comparator.comparing(BankTemplate::getName, String.CASE_INSENSITIVE_ORDER));
		return l;
	}

	public BankTemplate getActive()
	{
		return active;
	}

	public BankTemplate findByName(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (BankTemplate t : getTemplates())
		{
			if (name.equals(t.getName()))
			{
				return t;
			}
		}
		return null;
	}

	/** Sets the active template (null clears it) and persists the choice. */
	public void setActive(BankTemplate template)
	{
		this.active = template;
		if (template == null)
		{
			configManager.unsetConfiguration(BankTemplatesConfig.GROUP, BankTemplatesConfig.ACTIVE_TEMPLATE_KEY);
		}
		else
		{
			configManager.setConfiguration(BankTemplatesConfig.GROUP, BankTemplatesConfig.ACTIVE_TEMPLATE_KEY, template.getName());
		}
	}

	public boolean isActive(BankTemplate template)
	{
		return active != null && template != null && active.getName().equals(template.getName());
	}

	/**
	 * Saves a user template as a genuine edit: stamps {@code updatedAt} to now and writes it to disk.
	 * Returns false if the name collides with a preset.
	 */
	public boolean saveUserTemplate(BankTemplate template)
	{
		return saveUserTemplate(template, true);
	}

	/**
	 * Persists a template whose content the user did not touch (a refreshed import count, say) WITHOUT
	 * bumping {@code updatedAt}, so a background write never reads as an edit.
	 */
	public boolean saveUnchanged(BankTemplate template)
	{
		return saveUserTemplate(template, false);
	}

	private boolean saveUserTemplate(BankTemplate template, boolean markEdited)
	{
		if (template == null || template.getName() == null || template.getName().trim().isEmpty())
		{
			return false;
		}

		final String name = template.getName().trim();
		template.setName(name);
		template.setPreset(false);

		// Don't let a user template shadow a preset of the same name.
		for (BankTemplate p : presets)
		{
			if (p.getName().equalsIgnoreCase(name))
			{
				return false;
			}
		}

		if (markEdited)
		{
			template.setUpdatedAt(System.currentTimeMillis());
		}
		userTemplates.put(name, template);
		writeAsync(template);
		return true;
	}

	/**
	 * Renames a user template, moving its on-disk file and keeping the active-template config in sync.
	 * The template's name is its storage key (map key + file name), so this re-keys it rather than just
	 * setting the field. Returns false if the new name is blank or collides with a preset or another
	 * user template (case-insensitive); a no-op rename to the same name returns true.
	 */
	public boolean renameTemplate(BankTemplate template, String newName)
	{
		if (template == null || template.isPreset() || newName == null)
		{
			return false;
		}

		final String trimmed = newName.trim();
		if (trimmed.isEmpty())
		{
			return false;
		}

		final String oldName = template.getName();
		if (trimmed.equals(oldName))
		{
			return true;
		}

		// Don't shadow a preset, or clobber a different user template that already uses the name.
		for (BankTemplate p : presets)
		{
			if (p.getName().equalsIgnoreCase(trimmed))
			{
				return false;
			}
		}
		for (BankTemplate t : userTemplates.values())
		{
			if (t != template && t.getName().equalsIgnoreCase(trimmed))
			{
				return false;
			}
		}

		userTemplates.remove(oldName);
		template.setName(trimmed);
		userTemplates.put(trimmed, template);
		// A rename is a genuine edit.
		template.setUpdatedAt(System.currentTimeMillis());

		// Write the new file first, then drop the old one - but only if it's a different file (a rename that
		// only changes case or punctuation can map to the same safe file name, which we must not delete).
		final Path oldFile = fileFor(oldName);
		writeAsync(template);
		if (!fileFor(trimmed).equals(oldFile))
		{
			deleteAsync(oldName);
		}

		// The active template is tracked by name in config; if this is it, repoint the stored name.
		if (active == template)
		{
			configManager.setConfiguration(BankTemplatesConfig.GROUP, BankTemplatesConfig.ACTIVE_TEMPLATE_KEY, trimmed);
		}
		return true;
	}

	public void deleteUserTemplate(BankTemplate template)
	{
		if (template == null || template.isPreset())
		{
			return;
		}

		userTemplates.remove(template.getName());
		if (isActive(template))
		{
			setActive(null);
		}
		deleteAsync(template.getName());
	}

	private void writeAsync(BankTemplate template)
	{
		final String json = gson.toJson(template);
		final Path file = fileFor(template.getName());
		executor.execute(() ->
		{
			try
			{
				Files.createDirectories(STORAGE_DIR);
				Files.write(file, json.getBytes(StandardCharsets.UTF_8));
			}
			catch (IOException e)
			{
				log.warn("Failed to save bank template {}", file, e);
			}
		});
	}

	private void deleteAsync(String name)
	{
		final Path file = fileFor(name);
		executor.execute(() ->
		{
			try
			{
				Files.deleteIfExists(file);
			}
			catch (IOException e)
			{
				log.warn("Failed to delete bank template {}", file, e);
			}
		});
	}

	private static Path fileFor(String name)
	{
		final String safe = UNSAFE_FILENAME.matcher(name.trim().replace(' ', '_')).replaceAll("_");
		return STORAGE_DIR.resolve(safe + ".json");
	}
}

package com.banktemplates;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * An interactive mimic of the bank for previewing a {@link BankTemplate}: a row of tab buttons up
 * top and the item grid below, rendered at the template's designed column count. Clicking a tab
 * switches the grid, just like the real bank.
 */
final class TemplatePreview
{
	private static final int CELL = 36;
	// Minimum content width so preview windows are a consistent size regardless of description/columns.
	private static final int MIN_WIDTH = 320;

	private TemplatePreview()
	{
	}

	static JPanel build(ItemManager itemManager, ClientThread clientThread, BankTemplate template, String description,
		java.util.function.Consumer<TabLayout> onImportTab)
	{
		final int columns = template.getColumns();
		final List<TabLayout> tabs = new ArrayList<>(template.getTabs());
		tabs.sort(Comparator.comparingInt(TabLayout::getTab));

		final JPanel root = new JPanel(new BorderLayout(0, 6));
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel gridHolder = new JPanel(new BorderLayout());
		gridHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JScrollPane scroll = new JScrollPane(gridHolder,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		ThinScrollBarUI.style(scroll);

		// Tab buttons. WrapLayout so a bank with many tabs wraps onto further rows instead of being
		// clipped by the dialog width.
		final JPanel tabBar = new JPanel(new WrapLayout(FlowLayout.LEFT, 3, 2));
		tabBar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		final List<JButton> tabButtons = new ArrayList<>();
		// "Import this tab" copies the currently viewed tab - a numbered tab or the main "all items" view -
		// into one of your templates.
		final TabLayout[] current = {null};
		final JButton importBtn = onImportTab == null ? null : new JButton("Import this tab");
		for (int i = 0; i < tabs.size(); i++)
		{
			final TabLayout tab = tabs.get(i);
			final boolean isMain = tab.getTab() == BankTemplate.MAIN_TAB;
			// A bank tab's icon is a custom one if the template set it, else its first item (the game default).
			final int custom = isMain ? 0 : template.getTabIcon(tab.getTab());
			final int iconId = isMain ? 0 : custom > 0 ? custom : firstItem(tab.getLayout());
			final JButton b = new JButton(isMain ? "Main" : iconId > 0 ? "" : Integer.toString(tab.getTab()));
			if (iconId > 0)
			{
				itemManager.getImage(iconId).addTo(b);
				b.setToolTipText("Tab " + tab.getTab());
			}
			b.setFocusPainted(false);
			b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			b.setForeground(Color.WHITE);
			b.setBorder(BorderFactory.createEmptyBorder(2, iconId > 0 ? 3 : 8, 2, iconId > 0 ? 3 : 8));
			b.setMargin(new Insets(0, 0, 0, 0));
			final int[] columnsRef = {columns};
			b.addActionListener(e ->
			{
				for (JButton other : tabButtons)
				{
					other.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				}
				b.setBackground(ColorScheme.BRAND_ORANGE);
				current[0] = tab;
				gridHolder.removeAll();
				gridHolder.add(grid(itemManager, clientThread, BankTemplate.toArray(tab.getLayout()), columnsRef[0]), BorderLayout.NORTH);
				gridHolder.revalidate();
				gridHolder.repaint();
			});
			tabButtons.add(b);
			tabBar.add(b);
		}

		// Width that fits both the grid and the tab row on one line (so tabs default to one row, and wrap
		// only if the window is resized narrower), with a minimum so the window size is consistent whether
		// or not there's a description.
		final int contentWidth = Math.max(Math.max(columns * CELL + 28, tabBar.getPreferredSize().width + 12), MIN_WIDTH);
		root.setPreferredSize(new Dimension(contentWidth, 420));

		final JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		if (description != null && !description.isEmpty())
		{
			final JLabel desc = new JLabel("<html><body style='width:" + (contentWidth - 24) + "px'>"
				+ escape(description) + "</body></html>");
			desc.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			desc.setAlignmentX(Component.LEFT_ALIGNMENT);
			desc.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
			top.add(desc);
		}
		tabBar.setAlignmentX(Component.LEFT_ALIGNMENT);
		top.add(tabBar);

		root.add(top, BorderLayout.NORTH);
		root.add(scroll, BorderLayout.CENTER);

		if (importBtn != null)
		{
			importBtn.setFocusPainted(false);
			importBtn.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			importBtn.setForeground(Color.WHITE);
			importBtn.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 8));
			importBtn.setToolTipText("Copy the tab in view into one of your templates (or a new one).");
			importBtn.addActionListener(e ->
			{
				if (current[0] != null)
				{
					onImportTab.accept(current[0]);
				}
			});
			final JPanel bottom = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 4));
			bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);
			bottom.add(importBtn);
			root.add(bottom, BorderLayout.SOUTH);
		}

		// Select the first tab.
		if (!tabButtons.isEmpty())
		{
			tabButtons.get(0).doClick();
		}
		return root;
	}

	// Display name for a slot's item. MUST run on the client thread (getItemComposition asserts it);
	// use setItemTooltip from Swing code. Falls back to the id if unknown.
	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	static String itemName(ItemManager itemManager, int id)
	{
		try
		{
			final String name = itemManager.getItemComposition(id).getName();
			if (name != null && !name.isEmpty() && !"null".equals(name))
			{
				return name;
			}
		}
		catch (RuntimeException ignored)
		{
			// Unknown id (hand-edited template, or item this client version lacks) - fall through.
		}
		return "Item " + id;
	}

	// Sets a component's tooltip to an item's name, resolving the name on the client thread (required by
	// getItemComposition) and applying it back on the EDT. Safe to call from Swing code.
	static void setItemTooltip(JComponent comp, ItemManager itemManager, ClientThread clientThread, int id)
	{
		clientThread.invoke(() ->
		{
			final String name = itemName(itemManager, id);
			SwingUtilities.invokeLater(() -> comp.setToolTipText(name));
		});
	}

	// Fallback tab icon: the first real item in the tab.
	private static int firstItem(List<Integer> layout)
	{
		for (Integer v : layout)
		{
			if (v != null && v > 0 && v != BankTemplate.FILLER)
			{
				return v;
			}
		}
		return 0;
	}

	private static JPanel grid(ItemManager itemManager, ClientThread clientThread, int[] layout, int columns)
	{
		final int rows = Math.max(1, (layout.length + columns - 1) / columns);
		final JPanel grid = new JPanel(new GridLayout(rows, columns, 1, 1));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

		for (int i = 0; i < rows * columns; i++)
		{
			final JLabel cell = new JLabel();
			cell.setPreferredSize(new Dimension(CELL, CELL - 4));
			cell.setHorizontalAlignment(JLabel.CENTER);

			final int id = i < layout.length ? layout[i] : BankTemplate.EMPTY;
			if (id > 0 || id == BankTemplate.FILLER)
			{
				final AsyncBufferedImage img = itemManager.getImage(id);
				img.addTo(cell);
				// Name on hover, so you can identify items in the preview without owning them.
				setItemTooltip(cell, itemManager, clientThread, id);
			}
			grid.add(cell);
		}
		return grid;
	}
}

