/**
 * A self-styled search field: a magnifying-glass icon on the left, white text on a dark field, and a red
 * clear "x" that appears once you have typed something. Built directly rather than using the client's
 * IconTextField, whose flat text field renders unreadably in this plugin's panel context - here every
 * colour is under our control, so it stays readable and matches the rest of the client.
 */
final class SearchBar extends JPanel
{
	private final JTextField field = new JTextField();
	private final JButton clear = new JButton("×");
	private final List<Runnable> clearListeners = new ArrayList<>();

	SearchBar()
	{
		super(new BorderLayout(4, 0));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Non-opaque so paintComponent can draw the rounded body; the border strokes the matching outline,
		// giving the field the same corner radius as the template cards.
		setOpaque(false);
		setBorder(new RoundedBorder(ColorScheme.MEDIUM_GRAY_COLOR, new Insets(3, 8, 3, 6)));

		final JLabel icon = new JLabel(magnifier());
		icon.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
		add(icon, BorderLayout.WEST);

		field.setOpaque(false);
		field.setFont(FontManager.getRunescapeFont());
		field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		field.setForeground(Color.WHITE);
		field.setCaretColor(Color.WHITE);
		field.setBorder(null);
		add(field, BorderLayout.CENTER);

		clear.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		clear.setFont(FontManager.getRunescapeBoldFont());
		clear.setBorder(null);
		clear.setContentAreaFilled(false);
		clear.setFocusPainted(false);
		clear.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		clear.setToolTipText("Clear");
		clear.setVisible(false);
		clear.addActionListener(e ->
		{
			field.setText("");
			field.requestFocusInWindow();
			for (Runnable r : clearListeners)
			{
				r.run();
			}
		});
		add(clear, BorderLayout.EAST);

		field.getDocument().addDocumentListener(new DocumentListener()
		{
			private void update()
			{
				clear.setVisible(!field.getText().isEmpty());
			}

			@Override
			public void insertUpdate(DocumentEvent e)
			{
				update();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				update();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				update();
			}
		});
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		// The field is non-opaque, so paint its body here with the shared card corner radius.
		RoundedBorder.fill(g, this, getBackground());
		super.paintComponent(g);
	}

	// A simple magnifying glass (lens + handle) drawn at runtime, so there's no bundled asset to ship.
	private static ImageIcon magnifier()
	{
		final BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xA7A7A7));
		g.setStroke(new BasicStroke(1.6f));
		g.drawOval(2, 2, 7, 7);
		g.drawLine(9, 9, 12, 12);
		g.dispose();
		return new ImageIcon(img);
	}

	String getText()
	{
		return field.getText();
	}

	void setText(String text)
	{
		field.setText(text);
	}

	@Override
	public synchronized void addKeyListener(KeyListener l)
	{
		field.addKeyListener(l);
	}

	void addActionListener(ActionListener l)
	{
		field.addActionListener(l);
	}

	/** Runs when the red clear button empties the field, so callers can refresh their results. */
	void addClearListener(Runnable r)
	{
		clearListeners.add(r);
	}

	@Override
	public boolean requestFocusInWindow()
	{
		return field.requestFocusInWindow();
	}
}

package com.banktemplates;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.SoundEffectID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The in-bank face of the layout editor. While a template is being edited it draws a green "+" button
 * after the last slot (search and add an item without owning it) and lets you drag slots around to
 * rearrange them - all client-side, the real bank is never touched. Slot rectangles are captured during
 * {@link #render} (client thread) and the mouse handlers hit-test those cached rectangles, so input
 * handling never reads widgets off-thread.
 */
public class LayoutEditorOverlay extends Overlay implements MouseListener
{
	private static final Color ADD_COLOR = new Color(110, 200, 110);
	private static final Font PLUS_FONT = new Font("Arial", Font.PLAIN, 22);

	private static final int DRAG_THRESHOLD = 5;

	private final Client client;
	private final ItemIndex itemIndex;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final BankSearch bankSearch;
	private final LayoutEditor layoutEditor;
	private final ClientThread clientThread;
	private final BankTemplatesConfig config;
	private final BankLayoutRenderer renderer;

	// Captured each frame on the client thread, read by the (AWT-thread) mouse handlers.
	private volatile Rectangle[] slotRects = new Rectangle[0];
	private volatile int[] slotItems = new int[0];
	private volatile Rectangle addRect;
	private volatile Rectangle containerRect;
	private volatile int currentTab;
	// Native tab buttons (tab number -> bounds), so a slot can be dragged onto a tab to move it there.
	private volatile Map<Integer, Rectangle> tabRects = Collections.emptyMap();
	// The bank's "+" (add tab) button: dropping a slot here creates a new template tab.
	private volatile Rectangle newTabRect;
	// Overlay-drawn buttons (tab number -> bounds) for template tabs the real bank doesn't have. Drawn after
	// the native + and hit-tested by the mouse handlers (click to view, drag an item onto to move it there).
	private volatile Map<Integer, Rectangle> extraTabRects = Collections.emptyMap();
	// Native tab-background geometry (the bg sprite is a touch larger than the item icon), used to size and
	// place the overlay extra tabs so they match the real tabs exactly.
	private volatile Rectangle lastTabBg;
	private volatile int tabBgPitch;
	// A press armed on an overlay extra-tab button; a release on the same one (no drag) views that tab.
	private volatile int pressExtraTab = -1;

	// Drag state, set by the mouse handlers. The native bank drag draws the item on the cursor; we only
	// track this to know it's a drag (not a click) and for edge auto-scroll.
	private volatile int dragFrom = -1;
	private volatile java.awt.Point dragPoint;
	// A press is "armed" until it either moves past the threshold (-> drag/rearrange) or releases in
	// place (-> click passes through to the bank, e.g. withdraw).
	private volatile int pressSlot = -1;
	private volatile java.awt.Point pressPoint;
	// Where within the grabbed item you pressed, captured once at press time. The native drag-ghost keeps this
	// grab point under the cursor; we reuse it so our on-top ghost lines up, instead of re-deriving it from the
	// source slot each frame (the slot moves as the bank scrolls/re-lays-out mid-drag, skewing the ghost).
	private volatile int grabDx = 16;
	private volatile int grabDy = 16;
	// Tab-reorder drag: armed when a numbered tab button is pressed, promoted to dragTabBtn past the
	// threshold. Dropping it on another numbered tab reorders the template's tabs.
	private volatile int pressTabBtn = -1;
	private volatile int dragTabBtn = -1;
	// Whether the client itself considers a widget drag in progress. Only true once the pressed widget's
	// drag dead time/zone are exceeded, so it honours the vanilla drag delay and Anti Drag's settings
	// (including "on shift only"). Without this gate a fast withdraw click that slides a few pixels would
	// count as a drag and rearrange the template (issue #35).
	private volatile boolean nativeDragging;

	@Inject
	LayoutEditorOverlay(Client client, ItemIndex itemIndex, ItemManager itemManager, SpriteManager spriteManager,
		BankSearch bankSearch, LayoutEditor layoutEditor, ClientThread clientThread, BankTemplatesConfig config,
		BankLayoutRenderer renderer)
	{
		this.client = client;
		this.itemIndex = itemIndex;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		this.bankSearch = bankSearch;
		this.layoutEditor = layoutEditor;
		this.clientThread = clientThread;
		this.config = config;
		this.renderer = renderer;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Sampled on the client thread each frame for the AWT mouse handlers (matching the cached rects).
		nativeDragging = client.isDraggingWidget();

		// Editable whenever a user template is applied (always-on), or during an explicit edit session.
		final BankTemplate template = layoutEditor.liveTemplate();
		// Only edit in the bank when the editable template is the one actually applied/rendered. Editing a
		// template from the side panel doesn't activate it, so its window edits must not touch the bank.
		final boolean active = template != null
			&& layoutEditor.liveOverBank()
			&& (layoutEditor.isEditing() || (config.applyLayout() && !config.showReorgHelper()));
		if (!active)
		{
			clearCache();
			return null;
		}

		final Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (itemContainer == null || itemContainer.isHidden())
		{
			clearCache();
			return null;
		}

		// The viewed tab is just the native current tab - clicking an extra tab sets it to that tab's number,
		// even past the real bank's tab count, and the renderer fills the (empty) native view from the template.
		final int tab = client.getVarbitValue(VarbitID.BANK_CURRENTTAB);

		// A filtered bank (tag tab, search, Inventory Setups) shows something other than the template's
		// layout, so none of the slot / "+" / drag machinery below applies. The extra TAB BUTTONS must still
		// be drawn though: otherwise the virtual tabs vanish the moment a tag tab is opened, leaving no way
		// back to them. Draw just the tab strip and keep it clickable.
		if (BankLayoutRenderer.isBankFiltered(client))
		{
			slotRects = new Rectangle[0];
			slotItems = new int[0];
			addRect = null;
			containerRect = null;
			dragFrom = -1;
			dragPoint = null;
			pressSlot = -1;
			pressPoint = null;
			this.currentTab = tab;
			this.tabRects = captureTabRects();
			this.extraTabRects = drawExtraTabs(graphics, template, tab);
			return null;
		}
		final int[] layout = template.tabLayout(tab);
		final int len = layout == null ? 0 : layout.length;

		// Slots are located via the renderer's position->widget map (a widget's container index no longer
		// equals its rendered slot, since items are placed by identity for Inventory Setups compatibility).
		final Rectangle[] rects = new Rectangle[len];
		final int[] items = new int[len];
		for (int i = 0; i < len; i++)
		{
			final Widget c = renderer.slotWidgetAt(i);
			rects[i] = c != null ? c.getBounds() : null;
			// Use the widget's displayed item (the matched/owned variant), not the template's stored id, so the
			// drag-ghost over a virtual tab matches the actual item you're dragging instead of the stored one.
			items[i] = c != null && c.getItemId() > 0 ? c.getItemId() : layout[i];
		}

		// The "+" lives in the slot right after the layout. It can be scrolled out of view, where its
		// widget bounds sit over the bank's bottom buttons - only show/hit-test it when it's actually
		// inside the visible bank area.
		final Rectangle container = itemContainer.getBounds();
		// With the button switched off it belongs to an edit session only, so a template you are just
		// using leaves the bank alone. Nulling the rect also drops its click handling, not merely the
		// drawing, so the slot underneath behaves like any other.
		final boolean wantAdd = config.showAddButton() || layoutEditor.isEditing();
		Widget addChild = wantAdd ? renderer.slotWidgetAt(len) : null;
		// If another plugin (e.g. Inventory Setups) rearranged the bank so the slot after the layout now holds
		// a real item, move the "+" to the first genuinely-empty slot so it never covers - and blocks the
		// withdrawal of - an item.
		if (wantAdd && (addChild == null || addChild.getItemId() > 0))
		{
			final Widget empty = renderer.firstEmptySlot();
			if (empty != null)
			{
				addChild = empty;
			}
		}
		Rectangle add = addChild != null ? addChild.getBounds() : null;
		if (add != null && (container == null || !container.contains(add)))
		{
			add = null;
		}

		this.slotRects = rects;
		this.slotItems = items;
		this.addRect = add;
		this.containerRect = container;
		this.currentTab = tab;
		this.tabRects = captureTabRects();
		this.extraTabRects = drawExtraTabs(graphics, template, tab);
		// While dragging an item over an extra tab, the native drag-ghost is drawn under our overlay icon, so
		// draw the dragged item again on top so it reads as "over" the tab (like the real bank).
		final java.awt.Point dp = dragPoint;
		if (dragFrom >= 0 && dp != null && dragFrom < slotItems.length && slotItems[dragFrom] > 0)
		{
			final BufferedImage ghost = itemManager.getImage(slotItems[dragFrom]);
			if (ghost != null)
			{
				// Match the native drag-ghost: keep the grab point (where you pressed within the item) under
				// the cursor so the copies line up. grabDx/grabDy were captured at press time, so they stay
				// correct even when the source slot scrolls or re-lays-out during the drag.
				final int gx = dp.x - grabDx;
				final int gy = dp.y - grabDy;
				// Redraw it (semi-transparent, like the game's ghost) whenever the ghost rectangle overlaps an
				// overlay tab or the +, not just when the cursor point is inside - otherwise the ghost slips
				// behind the overlay tab icon as it approaches.
				final Rectangle ghostRect = new Rectangle(gx, gy, ghost.getWidth(), ghost.getHeight());
				if (overlapsOverlayTab(ghostRect))
				{
					final java.awt.Composite oldC = graphics.getComposite();
					graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.5f));
					graphics.drawImage(ghost, gx, gy, null);
					graphics.setComposite(oldC);
				}
			}
		}

		if (add != null && add.width > 0)
		{
			drawAddButton(graphics, add);
		}

		// The "Editing ..." banner is shown in the bank's real title bar (set by BankLayoutRenderer).

		// The native bank drag draws the item on the cursor, so we don't render our own ghost. We only read
		// the drag point here to auto-scroll the bank when the cursor nears the top/bottom edge.
		final int from = dragFrom;
		final java.awt.Point p = dragPoint;

		// While dragging near the top/bottom edge, auto-scroll the bank (like the native bank drag) so an
		// item can be dragged across many rows without holding click and using the scroll wheel together.
		if (from >= 0 && p != null)
		{
			final Rectangle cb = itemContainer.getBounds();
			if (cb != null && cb.height > 0)
			{
				final int edge = 24;
				int delta = 0;
				if (p.y < cb.y + edge)
				{
					delta = -12;
				}
				else if (p.y > cb.y + cb.height - edge)
				{
					delta = 12;
				}
				if (delta != 0)
				{
					final int max = Math.max(0, itemContainer.getScrollHeight() - itemContainer.getHeight());
					final int newY = Math.max(0, Math.min(max, itemContainer.getScrollY() + delta));
					if (newY != itemContainer.getScrollY())
					{
						itemContainer.setScrollY(newY);
						itemContainer.revalidateScroll();
						client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS, newY);
					}
				}
			}
		}

		return null;
	}

	private void drawAddButton(Graphics2D g, Rectangle b)
	{
		g.setColor(new Color(ADD_COLOR.getRed(), ADD_COLOR.getGreen(), ADD_COLOR.getBlue(), 60));
		g.fillRect(b.x, b.y, b.width, b.height);
		final Stroke old = g.getStroke();
		g.setColor(ADD_COLOR);
		g.setStroke(new BasicStroke(2f));
		g.drawRect(b.x, b.y, b.width, b.height);
		g.setStroke(old);

		g.setFont(PLUS_FONT);
		final int sw = g.getFontMetrics().stringWidth("+");
		final int ascent = g.getFontMetrics().getAscent();
		g.setColor(Color.WHITE);
		g.drawString("+", b.x + (b.width - sw) / 2, b.y + (b.height + ascent) / 2 - 2);
	}

	/**
	 * Draws buttons for template tabs the real bank doesn't have (numbered higher than your real tab count),
	 * after the native + button, and returns their hit-test rectangles. Empty if there's no tab bar to
	 * anchor to or no extra tabs.
	 */
	private Map<Integer, Rectangle> drawExtraTabs(Graphics2D g, BankTemplate template, int currentTab)
	{
		// Size and place from the native tab-background geometry so the buttons match the real tabs.
		final Rectangle lastReal = lastTabBg;
		final int pitch = tabBgPitch;
		if (lastReal == null || lastReal.width <= 0 || pitch <= 0)
		{
			this.newTabRect = null;
			return Collections.emptyMap();
		}
		int realTabCount = 0;
		for (int t : tabRects.keySet())
		{
			if (t >= 1)
			{
				realTabCount = Math.max(realTabCount, t);
			}
		}

		final Map<Integer, Rectangle> out = new HashMap<>();
		int numbered = 0;
		int k = 1;
		for (int tabNum : template.definedTabs())
		{
			if (tabNum == BankTemplate.MAIN_TAB)
			{
				continue;
			}
			numbered++;
			if (tabNum <= realTabCount)
			{
				continue;
			}
			final Rectangle r = new Rectangle(lastReal.x + pitch * k, lastReal.y, lastReal.width, lastReal.height);
			drawExtraTab(g, r, firstTabItem(template, tabNum), tabNum == currentTab);
			out.put(tabNum, r);
			k++;
		}
		// Draw the + after the extras (the native one is hidden), unless the template already has 9 tabs.
		if (numbered < 9)
		{
			final Rectangle plus = new Rectangle(lastReal.x + pitch * k, lastReal.y, lastReal.width, lastReal.height);
			drawPlus(g, plus);
			this.newTabRect = plus;
		}
		else
		{
			this.newTabRect = null;
		}
		return out;
	}

	private void drawPlus(Graphics2D g, Rectangle b)
	{
		final BufferedImage bg = spriteManager.getSprite(SpriteID.Banktabs.EMPTY, 0);
		if (bg != null)
		{
			g.drawImage(bg, b.x, b.y, b.width, b.height, null);
		}
		final BufferedImage glyph = spriteManager.getSprite(SpriteID.BanktabIcons.ADD, 0);
		if (glyph != null)
		{
			g.drawImage(glyph, b.x + (b.width - glyph.getWidth()) / 2, b.y + (b.height - glyph.getHeight()) / 2, null);
		}
	}

	private void drawExtraTab(Graphics2D g, Rectangle b, int itemId, boolean selected)
	{
		// Use the real bank tab sprites so the buttons match the native tabs exactly (selected = the same
		// highlighted sprite the game uses for the active tab).
		final BufferedImage bg = spriteManager.getSprite(
			selected ? SpriteID.Banktabs.SELECTED : SpriteID.Banktabs.TAB, 0);
		if (bg != null)
		{
			g.drawImage(bg, b.x, b.y, b.width, b.height, null);
		}
		if (itemId > 0)
		{
			final BufferedImage img = itemManager.getImage(itemId);
			if (img != null)
			{
				g.drawImage(img, b.x + (b.width - img.getWidth()) / 2, b.y + (b.height - img.getHeight()) / 2, null);
			}
		}
	}

	// The tab's icon: its chosen custom icon, else its first real item, or -1 if it has neither.
	private static int firstTabItem(BankTemplate template, int tabNum)
	{
		final int custom = template.getTabIcon(tabNum);
		if (custom > 0)
		{
			return custom;
		}
		final int[] layout = template.tabLayout(tabNum);
		if (layout != null)
		{
			for (int v : layout)
			{
				if (v > 0 && v != BankTemplate.FILLER)
				{
					return v;
				}
			}
		}
		return -1;
	}

	// After moving an item to another tab, if the tab we were viewing collapsed (its last item left), follow
	// the item to its destination so we're not stranded on a tab that no longer exists. Runs on the client
	// thread (called from clientThread.invoke).
	private void navigateIfCollapsed(int sourceTab, int dest)
	{
		if (dest < 0)
		{
			return;
		}
		final BankTemplate tpl = layoutEditor.liveTemplate();
		if (tpl != null && sourceTab != BankTemplate.MAIN_TAB && !tpl.definedTabs().contains(sourceTab))
		{
			client.setVarbit(VarbitID.BANK_CURRENTTAB, dest);
			bankSearch.layoutBank();
		}
	}

	// True if the rectangle overlaps any overlay-drawn extra tab or the + (so the drag-ghost should be
	// redrawn on top of them rather than slip underneath).
	private boolean overlapsOverlayTab(Rectangle r)
	{
		for (Rectangle tab : extraTabRects.values())
		{
			if (tab != null && tab.intersects(r))
			{
				return true;
			}
		}
		final Rectangle plus = newTabRect;
		return plus != null && plus.intersects(r);
	}

	// The overlay extra-tab whose button contains p, or -1.
	private int extraTabAt(java.awt.Point p)
	{
		for (Map.Entry<Integer, Rectangle> en : extraTabRects.entrySet())
		{
			final Rectangle r = en.getValue();
			if (r != null && r.contains(p))
			{
				return en.getKey();
			}
		}
		return -1;
	}

	private void outline(Graphics2D g, Rectangle b, Color c)
	{
		if (b == null || b.width <= 0)
		{
			return;
		}
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 70));
		g.fillRect(b.x, b.y, b.width, b.height);
		final Stroke old = g.getStroke();
		g.setColor(c);
		g.setStroke(new BasicStroke(2f));
		g.drawRect(b.x, b.y, b.width, b.height);
		g.setStroke(old);
	}

	private void clearCache()
	{
		slotRects = new Rectangle[0];
		slotItems = new int[0];
		addRect = null;
		containerRect = null;
		tabRects = Collections.emptyMap();
		newTabRect = null;
		extraTabRects = Collections.emptyMap();
		lastTabBg = null;
		tabBgPitch = 0;
		pressExtraTab = -1;
		dragFrom = -1;
		dragPoint = null;
		pressSlot = -1;
		pressPoint = null;
	}

	// ---- Mouse handling (AWT thread; hit-tests the cached rectangles only) -------------------

	@Override
	public java.awt.event.MouseEvent mousePressed(java.awt.event.MouseEvent e)
	{
		if (layoutEditor.liveTemplate() == null || !javax.swing.SwingUtilities.isLeftMouseButton(e))
		{
			return e;
		}
		final java.awt.Point p = e.getPoint();

		// The "+" add button has no withdraw conflict, so act on press.
		final Rectangle add = addRect;
		if (add != null && add.contains(p))
		{
			openSearch();
			e.consume();
			return e;
		}

		// Arm a potential drag but DON'T consume yet, so a plain click still reaches the bank (withdraw).
		final int slot = slotAt(p);
		if (slot >= 0)
		{
			pressSlot = slot;
			pressPoint = p;
			final Rectangle sr = slot < slotRects.length ? slotRects[slot] : null;
			grabDx = sr != null ? p.x - sr.x : 16;
			grabDy = sr != null ? p.y - sr.y : 16;
			dragFrom = -1;
			return e;
		}
		// Press on a numbered tab button -> arm a tab-reorder drag (a plain click still switches tabs).
		final int tabBtn = tabButtonAt(p);
		if (tabBtn >= 1)
		{
			pressTabBtn = tabBtn;
			pressPoint = p;
			dragTabBtn = -1;
			return e;
		}
		// Press on an overlay extra-tab button -> arm a click-to-view (it's also a drop target on release).
		// Don't consume: the press reaching the bank is what plays the native tab-select sound.
		final int extra = extraTabAt(p);
		if (extra >= 1)
		{
			pressExtraTab = extra;
			pressPoint = p;
		}
		return e;
	}

	// The numbered tab (1-9, real or virtual) whose button contains {@code p}, or -1. Used by the plugin to
	// add a "Set icon" entry to a bank tab's right-click menu.
	int tabAt(java.awt.Point p)
	{
		final int real = tabButtonAt(p);
		return real >= 1 ? real : extraTabAt(p);
	}

	// The numbered tab (1-9) whose button contains {@code p}, or -1 (the main/all-items tab isn't returned).
	private int tabButtonAt(java.awt.Point p)
	{
		for (Map.Entry<Integer, Rectangle> en : tabRects.entrySet())
		{
			final Rectangle r = en.getValue();
			if (r != null && en.getKey() >= 1 && r.contains(p))
			{
				return en.getKey();
			}
		}
		return -1;
	}

	@Override
	public java.awt.event.MouseEvent mouseDragged(java.awt.event.MouseEvent e)
	{
		final java.awt.Point press = pressPoint;
		// Movement alone isn't enough to call it a drag: the client must have engaged its own widget drag
		// too (past the drag dead time/zone), or a quick withdraw click that slides a few pixels rearranges
		// the template (issue #35). This also inherits Anti Drag's delay / on-shift-only settings.
		final boolean clientDragging = nativeDragging;
		if (dragFrom < 0 && pressSlot >= 0 && press != null && clientDragging && press.distance(e.getPoint()) > DRAG_THRESHOLD)
		{
			// Movement past the threshold means a drag (rearrange the template), not a click (withdraw).
			dragFrom = pressSlot;
		}
		if (dragTabBtn < 0 && pressTabBtn >= 1 && press != null && clientDragging && press.distance(e.getPoint()) > DRAG_THRESHOLD)
		{
			// Past the threshold from a tab button -> a tab-reorder drag, not a tab switch (click).
			dragTabBtn = pressTabBtn;
		}
		if (dragFrom >= 0 || dragTabBtn >= 0)
		{
			// Track the cursor for edge auto-scroll, but DON'T consume: the native bank drag runs underneath
			// (item on the cursor) and must complete so the client clears its own drag state.
			dragPoint = e.getPoint();
		}
		return e;
	}

	@Override
	public java.awt.event.MouseEvent mouseReleased(java.awt.event.MouseEvent e)
	{
		final int from = dragFrom;
		final int fromTab = dragTabBtn;
		final int pressExtra = pressExtraTab;
		pressSlot = -1;
		pressPoint = null;
		dragFrom = -1;
		dragPoint = null;
		pressTabBtn = -1;
		dragTabBtn = -1;
		pressExtraTab = -1;
		final java.awt.Point p = e.getPoint();

		// A tab button was dragged: dropped onto a different numbered tab (real or overlay extra) -> swap the
		// template's tabs.
		if (fromTab >= 1)
		{
			int destTab = tabButtonAt(p);
			if (destTab < 1)
			{
				destTab = extraTabAt(p);
			}
			if (destTab >= 1 && destTab != fromTab)
			{
				final int dest = destTab;
				clientThread.invoke(() -> layoutEditor.moveTab(fromTab, dest));
			}
			return e;
		}

		if (from < 0)
		{
			// A plain click on an overlay extra-tab button makes that tab the current bank tab. Setting the
			// native current-tab varbit lets the game draw the selection, title, hover and connector itself;
			// the real bank has no items there, so the renderer fills the view from the template.
			if (pressExtra >= 1 && extraTabAt(p) == pressExtra)
			{
				final int view = pressExtra;
				clientThread.invoke(() ->
				{
					client.setVarbit(VarbitID.BANK_CURRENTTAB, view);
					bankSearch.layoutBank();
					client.playSoundEffect(SoundEffectID.UI_BOOP);
				});
				e.consume();
			}
			return e;
		}
		final int tab = currentTab;

		// We deliberately DON'T consume the release. The native bank drag completes underneath us, which is
		// what clears the client's drag state (so the next click isn't swallowed into a withdraw of the item
		// we just dragged). Its real reorder is already blocked by the item's drag-complete listener; here we
		// just rewrite the template to match where the item was dropped.

		// Dropped onto the "+" button -> create a new tab from this item (like the real bank).
		final Rectangle newTab = newTabRect;
		if (newTab != null && newTab.contains(p))
		{
			clientThread.invoke(() -> navigateIfCollapsed(tab, layoutEditor.moveToNewTab(tab, from)));
			return e;
		}

		// Dropped onto an overlay extra-tab button -> move the item into that tab.
		final int extraDest = extraTabAt(p);
		if (extraDest >= 1 && extraDest != tab)
		{
			clientThread.invoke(() -> navigateIfCollapsed(tab, layoutEditor.moveToTab(tab, from, extraDest)));
			return e;
		}

		// Dropped onto a different tab's button -> move the item into that tab.
		for (Map.Entry<Integer, Rectangle> en : tabRects.entrySet())
		{
			final Rectangle r = en.getValue();
			if (r != null && r.contains(p) && en.getKey() != tab)
			{
				final int destTab = en.getKey();
				clientThread.invoke(() -> navigateIfCollapsed(tab, layoutEditor.moveToTab(tab, from, destTab)));
				return e;
			}
		}

		int target = slotAt(p);
		final Rectangle add = addRect;
		final Rectangle container = containerRect;
		if (target < 0)
		{
			if ((add != null && add.contains(p)) || (container != null && container.contains(p)))
			{
				target = slotRects.length; // dropped past the items -> move to the end
			}
		}

		if (target >= 0 && target != from)
		{
			final int dest = target;
			clientThread.invoke(() -> layoutEditor.moveSlot(tab, from, dest));
		}
		return e;
	}

	// Native bank tab buttons by tab number (1-9 = the item-icon children of Bankmain.TABS; 0 = the
	// all-items button, identified by its sprite).
	private Map<Integer, Rectangle> captureTabRects()
	{
		final Map<Integer, Rectangle> map = new HashMap<>();
		this.newTabRect = null;
		final Widget tabs = client.getWidget(InterfaceID.Bankmain.TABS);
		if (tabs == null)
		{
			this.lastTabBg = null;
			this.tabBgPitch = 0;
			return map;
		}
		int tab = 1;
		final java.util.List<Rectangle> bgs = new java.util.ArrayList<>();
		for (Widget[] group : new Widget[][]{tabs.getDynamicChildren(), tabs.getStaticChildren(), tabs.getNestedChildren()})
		{
			if (group == null)
			{
				continue;
			}
			for (Widget c : group)
			{
				if (c == null)
				{
					continue;
				}
				if (c.getSpriteId() == SpriteID.BanktabIcons.ALL_ITEMS)
				{
					map.put(BankTemplate.MAIN_TAB, c.getBounds());
				}
				else if (c.getSpriteId() == SpriteID.BanktabIcons.ADD)
				{
					// Hidden once the template has 9 tabs - don't make an invisible + a drop target.
					this.newTabRect = c.isHidden() ? null : c.getBounds();
				}
				else if (!c.isHidden() && (c.getSpriteId() == SpriteID.Banktabs.TAB
					|| c.getSpriteId() == SpriteID.Banktabs.SELECTED || c.getSpriteId() == SpriteID.Banktabs.HOVERED))
				{
					// Include HOVERED (a hovered tab swaps its background sprite - leaving it out would shift the
					// overlay extras), but skip HIDDEN backgrounds: with "hide items not in template" on, hidden
					// tab backgrounds keep stale far-right positions that would push the extras off-screen.
					bgs.add(c.getBounds());
				}
				else if (c.getItemId() > 0 && tab <= 9)
				{
					map.put(tab++, c.getBounds());
				}
			}
		}
		// The tab backgrounds (all-items + numbered, ascending x); the rightmost is the last real tab. Used to
		// size/place the overlay extra tabs to match the native tab buttons exactly.
		bgs.sort((a, b) -> a.x - b.x);
		// A selected/hovered tab can carry a second background at the same x as its base tab; collapse
		// duplicate x positions so the pitch (spacing between adjacent tabs) can't come out as 0 (which blanks
		// the overlay extra tabs).
		final java.util.List<Rectangle> distinct = new java.util.ArrayList<>();
		for (Rectangle r : bgs)
		{
			if (distinct.isEmpty() || distinct.get(distinct.size() - 1).x != r.x)
			{
				distinct.add(r);
			}
		}
		this.lastTabBg = distinct.isEmpty() ? null : distinct.get(distinct.size() - 1);
		this.tabBgPitch = distinct.size() >= 2 ? distinct.get(1).x - distinct.get(0).x : 0;
		return map;
	}

	private int slotAt(java.awt.Point p)
	{
		final Rectangle[] rects = slotRects;
		for (int i = 0; i < rects.length; i++)
		{
			if (rects[i] != null && rects[i].width > 0 && rects[i].contains(p))
			{
				return i;
			}
		}
		return -1;
	}

	private void openSearch()
	{
		final int tab = currentTab;
		javax.swing.SwingUtilities.invokeLater(() ->
			ItemSearch.open(client.getCanvas(), itemIndex, id ->
				clientThread.invoke(() ->
				{
					// An item can only live in one bank tab: don't add a duplicate. Already in this tab -> nothing
					// to do; already in another tab -> offer to move the original here; otherwise add it.
					final int[] loc = layoutEditor.find(id);
					if (loc == null)
					{
						layoutEditor.addItem(tab, id);
						return;
					}
					final String name = layoutEditor.displayName(id);
					if (loc[0] == tab)
					{
						javax.swing.SwingUtilities.invokeLater(() -> javax.swing.JOptionPane.showMessageDialog(
							null, name + " is already in this tab.", "Already in tab", javax.swing.JOptionPane.INFORMATION_MESSAGE));
						return;
					}
					final String from = layoutEditor.tabLabel(loc[0]);
					javax.swing.SwingUtilities.invokeLater(() ->
					{
						final int choice = javax.swing.JOptionPane.showConfirmDialog(null,
							name + " is already in " + from + ". Move it to this tab?",
							"Move item", javax.swing.JOptionPane.OK_CANCEL_OPTION, javax.swing.JOptionPane.QUESTION_MESSAGE);
						if (choice == javax.swing.JOptionPane.OK_OPTION)
						{
							clientThread.invoke(() -> layoutEditor.moveToTab(loc[0], loc[1], tab));
						}
					});
				})));
	}

	@Override
	public java.awt.event.MouseEvent mouseClicked(java.awt.event.MouseEvent e)
	{
		return e;
	}

	@Override
	public java.awt.event.MouseEvent mouseEntered(java.awt.event.MouseEvent e)
	{
		return e;
	}

	@Override
	public java.awt.event.MouseEvent mouseExited(java.awt.event.MouseEvent e)
	{
		return e;
	}

	@Override
	public java.awt.event.MouseEvent mouseMoved(java.awt.event.MouseEvent e)
	{
		return e;
	}
}

package com.banktemplates;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.client.eventbus.Subscribe;

/**
 * A dedicated high-priority event subscriber that pre-renders our out-of-range virtual tabs before RuneLite's
 * core Bank plugin (default priority 0) sums the visible widgets for the title value - so a virtual tab shows
 * its value in the title like a real tab does.
 *
 * <p>This lives outside {@link BankTemplatesPlugin} because RuneLite's EventBus requires a subscriber method
 * to be named {@code onScriptPreFired}, and the plugin already has one (at {@code -1f}, which must run after
 * Bank Tags sets its "Tag tab" title). A single class can't hold two methods with that name, so the earlier
 * pass gets its own class. It's registered/unregistered by the plugin's startUp/shutDown.
 */
@Singleton
class BankValuePreRenderer
{
	private final BankLayoutRenderer renderer;

	@Inject
	BankValuePreRenderer(BankLayoutRenderer renderer)
	{
		this.renderer = renderer;
	}

	@Subscribe(priority = 1f)
	public void onScriptPreFired(ScriptPreFired event)
	{
		renderer.preRenderVirtualTab(event);
	}
}

package com.banktemplates;

import java.util.ArrayList;
import java.util.List;

/**
 * A saved bank layout, organised per native bank tab.
 * <p>
 * Each {@link TabLayout} holds a flat, row-major grid for one tab ({@link #MAIN_TAB} = the main
 * "all items" view, 1-9 = the numbered tabs). Each slot is one of:
 * <ul>
 *     <li>a real item id (&gt; 0) - drawn real if owned, faded placeholder if not,</li>
 *     <li>{@link #EMPTY} (-1) - an empty slot,</li>
 *     <li>{@link #FILLER} - a reserved 🚫 slot.</li>
 * </ul>
 * {@link #getColumns()} is the grid width the template was designed for (default 8), so it renders
 * consistently regardless of the player's bank window width.
 */
public class BankTemplate
{
	public static final int EMPTY = -1;
	// Must remain 20594: this value is serialized into template JSON. ItemID.BANK_FILLER == 20594 exactly.
	public static final int FILLER = net.runelite.api.gameval.ItemID.BANK_FILLER;
	/** The main "all items" bank view. */
	public static final int MAIN_TAB = 0;

	private String name;
	private String description;
	private int columns;
	private List<TabLayout> tabs;

	// Legacy single-grid format (older saves / shared codes). Migrated into a MAIN_TAB layout on access.
	private List<Integer> layout;

	private transient boolean preset;

	// Community repository linkage (persisted): the repo id this template corresponds to, and whether
	// the local user owns it (uploaded it) and may therefore update/delete it on the repo.
	private Long repoId;
	private boolean owned;
	// Whether this template was shared anonymously - remembered so re-sharing (Update) keeps the choice.
	private boolean sharedAnonymously;
	// Wall-clock ms of the last edit. Only bumped by genuine user edits (import, create, layout edit,
	// rename), never by a background write such as a refreshed import count: the panel compares it before
	// and after the editor closes to tell an edit from a look, and "Recently updated" sorts on it.
	private long updatedAt;

	// The ORIGINAL uploader, stored when this template was imported from the community Browse list, so
	// its card can name them. Cleared once the user edits the template (it then becomes their own). Null
	// for self-made templates and presets.
	private OwnerProfile ownerProfile;

	// Popularity of this template's SHARED community copy (owned templates that were shared): how many
	// players imported it, and how many reported it. Refreshed from the catalogue index whenever Browse
	// loads it.
	private Integer shareDownloads;
	private Integer shareReports;

	/** Who shared an imported template, captured at import time for its card. */
	public static class OwnerProfile
	{
		public String name;            // author (or "Anonymous"), for the "by ..." line
		// The ORIGINAL community template's popularity, so an imported card shows how the shared
		// template is doing rather than the zeros of your own not-yet-shared copy. Cleared on the edit
		// that claims the template, so it never lingers once the card becomes yours.
		public Integer downloads;      // how many imported the original
		public Integer reports;        // how many reported the original
	}

	public BankTemplate()
	{
	}

	public Long getRepoId()
	{
		return repoId;
	}

	public void setRepoId(Long repoId)
	{
		this.repoId = repoId;
	}

	public boolean isOwned()
	{
		return owned;
	}

	public void setOwned(boolean owned)
	{
		this.owned = owned;
	}

	public OwnerProfile getOwnerProfile()
	{
		return ownerProfile;
	}

	public void setOwnerProfile(OwnerProfile ownerProfile)
	{
		this.ownerProfile = ownerProfile;
	}

	public Integer getShareDownloads()
	{
		return shareDownloads;
	}

	public void setShareDownloads(Integer shareDownloads)
	{
		this.shareDownloads = shareDownloads;
	}

	public Integer getShareReports()
	{
		return shareReports;
	}

	public void setShareReports(Integer shareReports)
	{
		this.shareReports = shareReports;
	}

	public boolean isSharedAnonymously()
	{
		return sharedAnonymously;
	}

	public void setSharedAnonymously(boolean sharedAnonymously)
	{
		this.sharedAnonymously = sharedAnonymously;
	}

	public long getUpdatedAt()
	{
		return updatedAt;
	}

	public void setUpdatedAt(long updatedAt)
	{
		this.updatedAt = updatedAt;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public String getDescription()
	{
		return description;
	}

	public void setDescription(String description)
	{
		this.description = description;
	}

	public boolean isPreset()
	{
		return preset;
	}

	void setPreset(boolean preset)
	{
		this.preset = preset;
	}

	public int getColumns()
	{
		return columns > 0 ? columns : BankLayoutRenderer.ITEMS_PER_ROW;
	}

	public void setColumns(int columns)
	{
		this.columns = columns;
	}

	// Several accessors below are synchronized on this template instance. The layout editor mutates the
	// per-tab lists (from the Swing thread and the client thread) while the renderer reads them on the
	// client thread, so editing and reading take the same lock to stay consistent.
	public synchronized List<TabLayout> getTabs()
	{
		normalize();
		return tabs;
	}

	// Lazily migrate the legacy single-grid field into a MAIN_TAB layout.
	private void normalize()
	{
		if (tabs == null)
		{
			tabs = new ArrayList<>();
		}
		if (tabs.isEmpty() && layout != null && !layout.isEmpty())
		{
			tabs.add(new TabLayout(MAIN_TAB, new ArrayList<>(layout)));
			layout = null;
		}
	}

	public synchronized void putTab(int tab, List<Integer> tabLayout)
	{
		normalize();
		// Keep any custom icon the tab already had - replacing its layout (e.g. moving items in) shouldn't
		// silently reset the icon the user chose for it.
		int icon = 0;
		for (TabLayout t : tabs)
		{
			if (t.getTab() == tab)
			{
				icon = t.getCustomIconId();
				break;
			}
		}
		tabs.removeIf(t -> t.getTab() == tab);
		final TabLayout added = new TabLayout(tab, tabLayout);
		added.setCustomIconId(icon);
		tabs.add(added);
	}

	/** The custom icon item id chosen for a tab's button, or 0 to use the tab's first item (the default). */
	public synchronized int getTabIcon(int tab)
	{
		normalize();
		for (TabLayout t : tabs)
		{
			if (t.getTab() == tab)
			{
				return t.getCustomIconId();
			}
		}
		return 0;
	}

	/** Sets (or clears, with 0) a tab's custom icon, creating the tab if it isn't defined yet. */
	public synchronized void setTabIcon(int tab, int iconId)
	{
		normalize();
		for (TabLayout t : tabs)
		{
			if (t.getTab() == tab)
			{
				t.setCustomIconId(iconId);
				return;
			}
		}
		final TabLayout created = new TabLayout(tab, new ArrayList<>());
		created.setCustomIconId(iconId);
		tabs.add(created);
	}

	/**
	 * The live, mutable slot list for a tab, creating an empty one if the template doesn't define it
	 * yet. Used by the layout editor to add/move/remove slots in place.
	 */
	public synchronized List<Integer> editableTab(int tab)
	{
		normalize();
		for (TabLayout t : tabs)
		{
			if (t.getTab() == tab)
			{
				return t.getLayout();
			}
		}
		final TabLayout created = new TabLayout(tab, new ArrayList<>());
		tabs.add(created);
		return created.getLayout();
	}

	/** A safe, independent copy of a tab's slots for display (e.g. the editor grid). */
	public synchronized List<Integer> copyTab(int tab)
	{
		return new ArrayList<>(editableTab(tab));
	}

	/** Drops a tab whose layout has become empty so it doesn't linger as a blank tab. */
	public synchronized void pruneTab(int tab)
	{
		normalize();
		tabs.removeIf(t -> t.getTab() == tab && t.getLayout().isEmpty());
	}

	/**
	 * Removes trailing empty numbered tabs - the highest-numbered tabs holding no real item (e.g. a tab left
	 * behind after all its items were moved away). Stops at the first non-empty tab from the top, so it never
	 * leaves a gap in the numbering. Pointless empty tabs otherwise count toward the 9-tab cap (hiding the +)
	 * and render as a blank tab button.
	 */
	public synchronized void pruneTrailingEmptyTabs()
	{
		normalize();
		for (int n = 9; n >= 1; n--)
		{
			final int[] lay = tabLayout(n);
			if (lay == null)
			{
				continue;
			}
			boolean hasItem = false;
			for (int v : lay)
			{
				if (v > 0 && v != FILLER)
				{
					hasItem = true;
					break;
				}
			}
			if (hasItem)
			{
				break;
			}
			final int num = n;
			tabs.removeIf(t -> t.getTab() == num);
		}
	}

	/**
	 * Removes a numbered tab and renumbers the higher tabs down to close the gap (like the real bank collapsing
	 * a tab). The main view (0) is never removed. No-op if the tab isn't defined.
	 */
	public synchronized void removeTab(int tab)
	{
		normalize();
		if (tab == MAIN_TAB)
		{
			return;
		}
		// Snapshot the surviving numbered tabs (their backing lists), renumbering anything above the removed
		// tab down by one.
		final List<TabLayout> survivors = new ArrayList<>();
		for (TabLayout t : tabs)
		{
			if (t.getTab() == MAIN_TAB || t.getTab() == tab)
			{
				continue;
			}
			final TabLayout moved = new TabLayout(t.getTab() > tab ? t.getTab() - 1 : t.getTab(), t.getLayout());
			moved.setCustomIconId(t.getCustomIconId());
			survivors.add(moved);
		}
		tabs.removeIf(t -> t.getTab() != MAIN_TAB);
		tabs.addAll(survivors);
	}

	/** Tabs this template defines, ascending, with the main view (0) sorting first for the editor. */
	public synchronized List<Integer> definedTabs()
	{
		normalize();
		final List<Integer> result = new ArrayList<>();
		for (TabLayout t : tabs)
		{
			result.add(t.getTab());
		}
		result.sort((a, b) -> editorOrder(a) - editorOrder(b));
		return result;
	}

	private static int editorOrder(int tab)
	{
		// Main/untabbed (0) sorts first in the editor (it's the "all items" view); numbered tabs follow.
		return tab == MAIN_TAB ? -1 : tab;
	}

	/**
	 * Swaps two numbered tabs, like dragging one bank tab onto another: {@code fromTab} and {@code toTab}
	 * exchange contents (their tab numbers stay put, so the rest of the tabs are untouched). The main view
	 * (0) is never involved. Returns the tab number now holding what was dragged ({@code toTab}), or -1 on a
	 * no-op (either isn't a numbered tab this template defines, or they're the same).
	 */
	public synchronized int moveTab(int fromTab, int toTab)
	{
		normalize();
		if (fromTab == MAIN_TAB || toTab == MAIN_TAB || fromTab == toTab)
		{
			return -1;
		}
		List<Integer> fromLayout = null;
		List<Integer> toLayout = null;
		int fromIcon = 0;
		int toIcon = 0;
		for (TabLayout t : tabs)
		{
			if (t.getTab() == fromTab)
			{
				fromLayout = t.getLayout();
				fromIcon = t.getCustomIconId();
			}
			else if (t.getTab() == toTab)
			{
				toLayout = t.getLayout();
				toIcon = t.getCustomIconId();
			}
		}
		if (fromLayout == null || toLayout == null)
		{
			return -1;
		}
		// Exchange the two tabs' contents (and their icons - the icon belongs to the items), keeping their
		// numbers (drag tab 3 onto tab 1 -> tab 1 shows tab 3's items and icon, and vice versa).
		tabs.removeIf(t -> t.getTab() == fromTab || t.getTab() == toTab);
		final TabLayout movedTo = new TabLayout(toTab, fromLayout);
		movedTo.setCustomIconId(fromIcon);
		final TabLayout movedFrom = new TabLayout(fromTab, toLayout);
		movedFrom.setCustomIconId(toIcon);
		tabs.add(movedTo);
		tabs.add(movedFrom);
		return toTab;
	}

	/** A deep, independent copy - used to snapshot a template before editing so edits can be reverted. */
	public synchronized BankTemplate copy()
	{
		normalize();
		final BankTemplate c = new BankTemplate();
		c.name = name;
		c.description = description;
		c.columns = columns;
		c.repoId = repoId;
		c.owned = owned;
		c.sharedAnonymously = sharedAnonymously;
		c.updatedAt = updatedAt;
		c.preset = preset;
		c.tabs = new ArrayList<>();
		for (TabLayout t : tabs)
		{
			final TabLayout copy = new TabLayout(t.getTab(), new ArrayList<>(t.getLayout()));
			copy.setCustomIconId(t.getCustomIconId());
			c.tabs.add(copy);
		}
		return c;
	}

	/** Replaces this template's tab layouts with those of {@code other} (used when reverting edits). */
	public synchronized void restoreTabsFrom(BankTemplate other)
	{
		normalize();
		other.normalize();
		tabs.clear();
		for (TabLayout t : other.tabs)
		{
			final TabLayout copy = new TabLayout(t.getTab(), new ArrayList<>(t.getLayout()));
			copy.setCustomIconId(t.getCustomIconId());
			tabs.add(copy);
		}
		columns = other.columns;
	}

	/** Layout for a native tab as a primitive array, or {@code null} if this template doesn't define it. */
	public synchronized int[] tabLayout(int tab)
	{
		normalize();
		for (TabLayout t : tabs)
		{
			if (t.getTab() == tab)
			{
				return toArray(t.getLayout());
			}
		}
		return null;
	}

	/** Total real items across all tabs (excludes empty and filler slots). */
	public synchronized int itemCount()
	{
		normalize();
		int n = 0;
		for (TabLayout t : tabs)
		{
			for (Integer v : t.getLayout())
			{
				if (v != null && v > 0 && v != FILLER)
				{
					n++;
				}
			}
		}
		return n;
	}

	public synchronized int tabCount()
	{
		normalize();
		return tabs.size();
	}

	static int[] toArray(List<Integer> list)
	{
		if (list == null)
		{
			return new int[0];
		}
		final int[] a = new int[list.size()];
		for (int i = 0; i < a.length; i++)
		{
			final Integer v = list.get(i);
			a[i] = v == null ? EMPTY : v;
		}
		return a;
	}
}

package com.banktemplates;

import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Variant collapsing, with a supplement for families RuneLite's own mapping misses.
 *
 * Everywhere this plugin compares "is the item in this slot the one the template wants", it collapses
 * variants first, so holding a different version of an item never counts as the wrong item. That is
 * normally {@link ItemVariationMapping}, but its data is incomplete: some recoloured sets are simply
 * absent from it, and an absent item maps to itself.
 *
 * The prospector set is the case that surfaced it (issue #37). Base prospector pieces are grouped -
 * 12013 and 29472 both map to "prospector helmet" - while the GOLDEN pieces sit in no group at all.
 * A template built with golden prospector therefore never matched a player's ordinary prospector, and
 * the reorganise helper told them to move a helmet that was already exactly where it belonged, down
 * to the bottom of the tab with the items the template does not want.
 *
 * The rest of the supplement covers the same shape of gap: forestry and lumberjack, spirit angler and
 * angler, forestry basket and log basket, radiant oathplate, sanguine torva, twisted ancestral.
 *
 * Only add a family here after confirming RuneLite really does leave it ungrouped, and that the pieces
 * are genuinely interchangeable for the purpose of "does this slot hold the right thing" - a recolour
 * or an upgrade of the same item, not a different item that merely shares a name. Most sets need no
 * entry: crystal armour, the crystal crown, bow of faerdhinen and blade of saeldor already carry all
 * eight elven clan recolours in RuneLite's own groups, as do slayer helmets, black masks and graceful.
 */
final class ItemVariants
{
	private ItemVariants()
	{
	}

	/** Extra variant -> base links, for sets RuneLite's item_variations.json does not group. */
	private static final Map<Integer, Integer> EXTRA = new HashMap<>();

	static
	{
		// Golden prospector (Motherlode Mine recolour) -> ordinary prospector. Verified against
		// RuneLite 1.12.30's item_variations.json: every base piece is grouped, every golden one is not.
		EXTRA.put(25549, 12013); // Golden prospector helmet -> Prospector helmet
		EXTRA.put(25551, 12014); // Golden prospector jacket -> Prospector jacket
		EXTRA.put(25553, 12015); // Golden prospector legs   -> Prospector legs
		EXTRA.put(25555, 12016); // Golden prospector boots  -> Prospector boots

		// Forestry outfit (anima-infused bark recolour) -> lumberjack. Same woodcutting bonus,
		// and RuneLite groups neither side, so the two sets never matched each other.
		EXTRA.put(28173, 10941); // Forestry hat   -> Lumberjack hat
		EXTRA.put(28169, 10939); // Forestry top   -> Lumberjack top
		EXTRA.put(28171, 10940); // Forestry legs  -> Lumberjack legs
		EXTRA.put(28175, 10933); // Forestry boots -> Lumberjack boots

		// Spirit angler -> angler. Keyed on 25592, the base of RuneLite's own "spirit angler headband"
		// group, so its second member (31252) collapses with it rather than being left behind.
		EXTRA.put(25592, 13258); // Spirit angler headband -> Angler hat
		EXTRA.put(25594, 13259); // Spirit angler top      -> Angler top
		EXTRA.put(25596, 13260); // Spirit angler waders   -> Angler waders
		EXTRA.put(25598, 13261); // Spirit angler boots    -> Angler boots

		// Forestry basket -> log basket, the upgrade of the same storage item. Both sides are grouped,
		// but as two separate groups, so this links group base to group base and the open forms
		// (28145 and 28142) follow their own groups.
		EXTRA.put(28143, 28140); // Forestry basket -> Log basket

		// Radiant oathplate -> oathplate.
		EXTRA.put(30777, 30750); // Radiant oathplate helm  -> Oathplate helm
		EXTRA.put(30779, 30753); // Radiant oathplate chest -> Oathplate chest
		EXTRA.put(30781, 30756); // Radiant oathplate legs  -> Oathplate legs

		// Sanguine torva -> torva. The targets are the ordinary pieces; RuneLite maps those onto the
		// damaged ids (26376/26378/26380), which is the group identity the rest of the plugin sees.
		EXTRA.put(28254, 26382); // Sanguine torva full helm -> Torva full helm
		EXTRA.put(28256, 26384); // Sanguine torva platebody -> Torva platebody
		EXTRA.put(28258, 26386); // Sanguine torva platelegs -> Torva platelegs

		// Corrupted voidwaker -> voidwaker, the other completed form. RuneLite groups the ordinary and
		// deadman voidwakers together and leaves the corrupted one out. The blade, hilt and gem stay
		// separate: they are the pieces you bank before assembling one, not another finished weapon.
		EXTRA.put(28531, 27690); // Corrupted voidwaker -> Voidwaker

		// Twisted ancestral -> ancestral. The colour kit (24670) is deliberately absent: it is a
		// separate item a player can bank on its own, not a robe.
		EXTRA.put(24664, 21018); // Twisted ancestral hat         -> Ancestral hat
		EXTRA.put(24666, 21021); // Twisted ancestral robe top    -> Ancestral robe top
		EXTRA.put(24668, 21024); // Twisted ancestral robe bottom -> Ancestral robe bottom
	}

	/**
	 * The base id for {@code itemId}, collapsing recolours and other variants onto one identity.
	 * Falls back to RuneLite's mapping, which returns the id itself when it knows no group.
	 *
	 * The supplement is consulted both before and after that mapping. Some variant sets are groups in
	 * their own right rather than loose ids - spirit angler headband holds 25592 and 31252, forestry
	 * basket holds the closed and open forms - so a supplement keyed on the group's base only reaches
	 * the other members once RuneLite has collapsed them onto it first.
	 */
	static int base(int itemId)
	{
		final int canonical = ItemVariationMapping.map(itemId);
		Integer extra = EXTRA.get(itemId);
		if (extra == null)
		{
			extra = EXTRA.get(canonical);
		}
		return extra != null ? ItemVariationMapping.map(extra) : canonical;
	}

	/**
	 * Every id that counts as {@code baseId}, including the supplemented ones. Needed as well as
	 * {@link #base(int)} because matching runs in both directions: a template asking for the golden
	 * piece has to accept the ordinary one, and a template asking for the ordinary piece has to accept
	 * the golden one. RuneLite's list only knows the half it grouped.
	 */
	static Collection<Integer> variations(int baseId)
	{
		final Set<Integer> out = new LinkedHashSet<>(ItemVariationMapping.getVariations(baseId));
		out.add(baseId);
		for (Map.Entry<Integer, Integer> e : EXTRA.entrySet())
		{
			if (ItemVariationMapping.map(e.getValue()) == baseId)
			{
				out.add(e.getKey());
				// Pull in the rest of the variant's own group, if it has one, so linking to its base
				// brings its siblings along: the open forestry basket, the second angler headband.
				out.addAll(ItemVariationMapping.getVariations(e.getKey()));
			}
		}
		return out;
	}
}

package com.banktemplates;

import java.util.ArrayList;
import java.util.List;

/**
 * The layout for a single native bank tab. {@code tab} 0 is the main "all items" view; 1-9 are the
 * numbered tabs.
 */
class TabLayout
{
	private int tab;
	private List<Integer> layout = new ArrayList<>();
	// A chosen icon item id for this tab's button; 0 means "use the tab's first item" (the default).
	private int customIconId;

	TabLayout()
	{
	}

	TabLayout(int tab, List<Integer> layout)
	{
		this.tab = tab;
		this.layout = layout != null ? layout : new ArrayList<>();
	}

	int getTab()
	{
		return tab;
	}

	int getCustomIconId()
	{
		return customIconId;
	}

	void setCustomIconId(int customIconId)
	{
		this.customIconId = customIconId;
	}

	/**
	 * The live, mutable slot list for this tab. Callers that edit a template (the layout editor) rely
	 * on this being the backing list so their changes stick; everyone else just reads it.
	 */
	List<Integer> getLayout()
	{
		if (layout == null)
		{
			layout = new ArrayList<>();
		}
		return layout;
	}
}

package com.banktemplates;

import java.util.List;

/**
 * One entry of the catalogue's index.json: a template's metadata, without its layout. The layout is a
 * separate immutable file (see {@link TemplateRepositoryClient#fetchLayout}) fetched only when the
 * player previews or imports.
 */
class RemoteTemplate
{
	long id;
	// Bumped on every edit; names the layout file for this version of the template.
	int rev;
	String name;
	String author;
	// Set by the server when the uploader chose to share anonymously: clients show "Anonymous" instead
	// of the author's name (the server still keeps the real name privately for moderation).
	boolean anonymous;
	String description;
	long created;
	long updated;
	int downloads;
	// Imports in the last 30 days, for the "Popular" sort.
	int recent;
	int reports;
	// Distinct item ids across every tab, so a card can say how big the template is without its layout.
	int items;
	int columns;
	List<TabRef> tabs;

	/** One tab of the index entry: its number and the icon its bank button would show (0 when empty). */
	static class TabRef
	{
		int tab;
		int icon;
	}

	int tabCount()
	{
		return tabs == null ? 0 : tabs.size();
	}

	/** Builds the local template from this entry's name and description plus a fetched layout. */
	BankTemplate toTemplate(TemplateRepositoryClient.LayoutFile layout)
	{
		final BankTemplate t = new BankTemplate();
		t.setName(name);
		t.setDescription(description);
		t.setColumns(layout.columns > 0 ? layout.columns : columns);
		if (layout.tabs != null)
		{
			for (TabLayout tl : layout.tabs)
			{
				t.putTab(tl.getTab(), tl.getLayout());
				// The uploader's chosen tab icons are part of the layout they shared, so an import gets
				// them too. putTab can't carry them here: it only keeps an icon a tab already had, and
				// this template was built empty just above.
				t.setTabIcon(tl.getTab(), tl.getCustomIconId());
			}
		}
		return t;
	}
}

package com.banktemplates;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;

/**
 * The bundled patch notes. The newest entry's {@link Entry#version} is treated as this build's version;
 * the side panel shows the newest entry's notes as an "Updates" tab until the user dismisses it.
 * <p>
 * This is purely local (no network) - when the Plugin Hub auto-updates the plugin, the new build ships
 * with a new newest entry, which is how "a new version went live" is detected.
 */
final class Changelog
{
	static final class Entry
	{
		String version;
		List<String> notes;
		List<String> knownIssues;
	}

	private Changelog()
	{
	}

	/** The newest changelog entry, or {@code null} if none could be loaded. */
	static Entry latest(Gson gson)
	{
		final List<Entry> all = load(gson);
		return all.isEmpty() ? null : all.get(0);
	}

	/** All changelog entries, newest first (full update history). */
	static List<Entry> all(Gson gson)
	{
		return load(gson);
	}

	private static List<Entry> load(Gson gson)
	{
		try (InputStream in = Changelog.class.getResourceAsStream("/com/banktemplates/changelog.json"))
		{
			if (in == null)
			{
				return Collections.emptyList();
			}
			final Entry[] entries = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Entry[].class);
			return entries == null ? Collections.emptyList() : java.util.Arrays.asList(entries);
		}
		catch (Exception e)
		{
			return Collections.emptyList();
		}
	}
}

