	// Copies one tab from a previewed template into a template of the user's choice (an existing one, or a
	// brand-new one). A numbered tab is appended as the destination's next free numbered tab; the main
	// ("all items") view replaces the destination's main view. Lets you mix tabs from different templates
	// without rebuilding them by hand. Source identity doesn't matter - only the layout.
	private void importTabInto(TabLayout source)
	{
		if (source == null)
		{
			return;
		}
		final boolean isMain = source.getTab() == BankTemplate.MAIN_TAB;
		final List<Integer> layout = new ArrayList<>(source.getLayout());

		final List<BankTemplate> dests = templateManager.getUserTemplates();
		final String newOption = "+ New template...";
		final List<String> options = new ArrayList<>();
		for (BankTemplate t : dests)
		{
			options.add(t.getName());
		}
		options.add(newOption);

		final String choice = (String) JOptionPane.showInputDialog(this, "Import this tab into:", "Import tab",
			JOptionPane.PLAIN_MESSAGE, null, options.toArray(), options.get(0));
		if (choice == null)
		{
			return;
		}

		if (newOption.equals(choice))
		{
			final String input = JOptionPane.showInputDialog(this,
				"Name for the new template (max " + MAX_NAME_LENGTH + " chars):", "New template");
			if (input == null || input.trim().isEmpty())
			{
				return;
			}
			final BankTemplate t = new BankTemplate();
			t.setName(uniqueName(capName(input)));
			t.setColumns(BankTemplatesPlugin.ITEMS_PER_ROW);
			if (isMain)
			{
				// The main view becomes the new template's main view.
				t.putTab(BankTemplate.MAIN_TAB, layout);
			}
			else
			{
				t.putTab(BankTemplate.MAIN_TAB, new ArrayList<>());
				t.putTab(1, layout);
			}
			if (templateManager.saveUserTemplate(t))
			{
				rebuildOnEdt();
				JOptionPane.showMessageDialog(this, "Created \"" + t.getName() + "\" with the imported tab.",
					"Imported tab", JOptionPane.INFORMATION_MESSAGE);
			}
			else
			{
				JOptionPane.showMessageDialog(this, "Could not create that template.", "Import failed", JOptionPane.ERROR_MESSAGE);
			}
			return;
		}

		final BankTemplate dest = templateManager.findByName(choice);
		if (dest == null || dest.isPreset())
		{
			return;
		}

		if (isMain)
		{
			// The main view replaces the destination's main view. Confirm first when that would discard
			// existing main-view items, since the replace is destructive.
			if (hasRealItems(dest.tabLayout(BankTemplate.MAIN_TAB))
				&& JOptionPane.showConfirmDialog(this,
					"Replace the main view of \"" + dest.getName() + "\" with this one? "
						+ "Its current main-view items will be removed.",
					"Replace main view", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE)
					!= JOptionPane.OK_OPTION)
			{
				return;
			}
			dest.putTab(BankTemplate.MAIN_TAB, layout);
			// An item can only live in one bank tab, so release any item this view brings in from wherever
			// it already sat in the destination's numbered tabs - it "moves" to the main view.
			final int released = releaseDuplicates(dest, BankTemplate.MAIN_TAB, layout);
			templateManager.saveUserTemplate(dest);
			rebuildOnEdt();
			final String extra = released > 0
				? " Moved " + released + " item" + (released == 1 ? "" : "s") + " out of other tabs (they can't be in two tabs at once)."
				: "";
			JOptionPane.showMessageDialog(this, "Replaced the main view of \"" + dest.getName() + "\"." + extra,
				"Imported tab", JOptionPane.INFORMATION_MESSAGE);
			return;
		}

		final int free = nextFreeTab(dest.definedTabs());
		if (free < 0)
		{
			JOptionPane.showMessageDialog(this, "\"" + dest.getName() + "\" already has the maximum of 9 tabs.",
				"No free tab", JOptionPane.WARNING_MESSAGE);
			return;
		}
		dest.putTab(free, layout);
		// An item can only live in one bank tab, so release any item this tab brings in from wherever it
		// already sat in the destination - it "moves" to the imported tab.
		final int released = releaseDuplicates(dest, free, layout);
		templateManager.saveUserTemplate(dest);
		rebuildOnEdt();
		final String extra = released > 0
			? " Moved " + released + " item" + (released == 1 ? "" : "s") + " out of other tabs (they can't be in two tabs at once)."
			: "";
		JOptionPane.showMessageDialog(this, "Added the tab to \"" + dest.getName() + "\" as tab " + free + "." + extra,
			"Imported tab", JOptionPane.INFORMATION_MESSAGE);
	}

	// Releases (removes, shifting the rest up) any real item the newly imported tab contains from the
	// destination's other tabs, so each item lives in a single tab. Fillers and empty slots are left alone.
	// Returns how many slots were released.
	private static int releaseDuplicates(BankTemplate dest, int importedTab, List<Integer> importedLayout)
	{
		final java.util.Set<Integer> imported = new java.util.HashSet<>();
		for (Integer v : importedLayout)
		{
			if (v != null && v > 0 && v != BankTemplate.FILLER)
			{
				imported.add(v);
			}
		}
		if (imported.isEmpty())
		{
			return 0;
		}

		int released = 0;
		for (Integer t : dest.definedTabs())
		{
			if (t == importedTab)
			{
				continue;
			}
			final List<Integer> layout = dest.copyTab(t);
			final List<Integer> kept = new ArrayList<>(layout.size());
			for (Integer v : layout)
			{
				if (v != null && imported.contains(v))
				{
					released++;
					continue;
				}
				kept.add(v);
			}
			if (kept.size() != layout.size())
			{
				dest.putTab(t, kept);
			}
		}
		return released;
	}

	// Whether a tab layout holds at least one real item (not empty, not filler). Null layout -> false.
	private static boolean hasRealItems(int[] layout)
	{
		if (layout == null)
		{
			return false;
		}
		for (int v : layout)
		{
			if (v > 0 && v != BankTemplate.FILLER)
			{
				return true;
			}
		}
		return false;
	}

	// The first numbered tab (1-9) a template doesn't already define, or -1 when all nine are taken.
	private static int nextFreeTab(List<Integer> defined)
	{
		for (int t = 1; t <= 9; t++)
		{
			if (!defined.contains(t))
			{
				return t;
			}
		}
		return -1;
	}

	/**
	 * Shows {@code content} in a non-modal window placed beside the client, so the game stays clickable
	 * while it's open (the old modal dialog blocked the whole client). Falls back to screen-centre when
	 * the owner window can't be located.
	 */
	private void showSideDialog(String title, JComponent content)
	{
		final Window owner = SwingUtilities.getWindowAncestor(this);
		final JDialog dialog = new JDialog(owner, title, Dialog.ModalityType.MODELESS);
		dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
		dialog.getContentPane().setBackground(ColorScheme.DARK_GRAY_COLOR);
		dialog.setContentPane(content);
		dialog.pack();

		if (owner != null)
		{
			final Rectangle screen = owner.getGraphicsConfiguration().getBounds();
			final Point loc = owner.getLocationOnScreen();
			// Prefer the left of the client; if there's no room there, the right.
			int x = loc.x - dialog.getWidth() - 8;
			if (x < screen.x)
			{
				x = loc.x + owner.getWidth() + 8;
			}
			// Keep the whole window on the client's screen. A maximised/fullscreen client leaves no room
			// beside it, which used to push the window off-screen so "View" looked like it did nothing.
			x = Math.max(screen.x, Math.min(x, screen.x + screen.width - dialog.getWidth()));
			final int y = Math.max(screen.y, Math.min(loc.y, screen.y + screen.height - dialog.getHeight()));
			dialog.setLocation(x, y);
		}
		else
		{
			dialog.setLocationRelativeTo(null);
		}
		dialog.setVisible(true);
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.banktemplates;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

/**
 * Snapshots the player's current bank into a {@link BankTemplate}, one layout per native tab.
 * <p>
 * The bank container is ordered tab 1, tab 2, … tab 9, then the main ("all items") view. The number
 * of items in each numbered tab is held in {@code BANK_TAB_1..9}, so we slice the container by those
 * counts; whatever's left is the main view.
 */
final class BankCapture
{
	// Package-visible: the bank-snapshot sync slices the container by the same per-tab counts.
	static final int[] TAB_COUNT_VARBITS = {
		VarbitID.BANK_TAB_1, VarbitID.BANK_TAB_2, VarbitID.BANK_TAB_3, VarbitID.BANK_TAB_4,
		VarbitID.BANK_TAB_5, VarbitID.BANK_TAB_6, VarbitID.BANK_TAB_7, VarbitID.BANK_TAB_8,
		VarbitID.BANK_TAB_9
	};

	private BankCapture()
	{
	}

	/**
	 * Captures the open bank. Must run on the client thread. Returns {@code null} if the bank is
	 * closed or empty.
	 */
	static BankTemplate capture(Client client, ItemManager itemManager, String name)
	{
		final ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			return null;
		}

		final Item[] items = bank.getItems();
		if (items.length == 0)
		{
			return null;
		}

		final BankTemplate template = new BankTemplate();
		template.setName(name);
		template.setColumns(BankLayoutRenderer.ITEMS_PER_ROW);

		int idx = 0;
		for (int tab = 1; tab <= 9; tab++)
		{
			final int count = client.getVarbitValue(TAB_COUNT_VARBITS[tab - 1]);
			if (count <= 0)
			{
				continue;
			}
			final List<Integer> layout = new ArrayList<>();
			for (int k = 0; k < count && idx < items.length; k++, idx++)
			{
				layout.add(slot(items[idx], itemManager));
			}
			if (!layout.isEmpty())
			{
				template.putTab(tab, layout);
			}
		}

		// Everything remaining is the main (tab 0) view.
		final List<Integer> main = new ArrayList<>();
		for (; idx < items.length; idx++)
		{
			main.add(slot(items[idx], itemManager));
		}
		if (!main.isEmpty())
		{
			template.putTab(BankTemplate.MAIN_TAB, main);
		}

		return template.tabCount() > 0 ? template : null;
	}

	private static int slot(Item item, ItemManager itemManager)
	{
		final int id = item.getId();
		if (id <= 0)
		{
			return BankTemplate.EMPTY;
		}
		// A bank filler (the 🚫 reserved-slot item) is captured as a FILLER slot, never a real item, so it's
		// never counted in the template's item totals or the "x / y items" owned count.
		if (id == BankTemplate.FILLER)
		{
			return BankTemplate.FILLER;
		}
		return itemManager.canonicalize(id);
	}
}

package com.banktemplates;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.awt.Window;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JViewport;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * A small non-modal "Add item" picker: type a name, click a result to add that item to the layout. It
 * stays open after each pick so several items can be added in a row. Adding an item never requires you
 * to own it - the editor places it as a faded placeholder.
 * <p>
 * Searches the full {@link ItemIndex} (every item by name, including untradeables), not just GE-priced
 * items, so things like Barrows gloves, Arclight and Emberlight can be added.
 */
final class ItemSearch
{
	private static final int MAX_RESULTS = 40;

	private ItemSearch()
	{
	}

	/**
	 * Opens the picker beside {@code parent}. {@code onPick} is called (on the EDT) with each chosen
	 * item id, and the picker stays open so several items can be added in a row.
	 */
	static void open(Component parent, ItemIndex itemIndex, IntConsumer onPick)
	{
		open(parent, itemIndex, onPick, false);
	}

	/**
	 * Opens the picker beside {@code parent}. {@code onPick} is called (on the EDT) with each chosen
	 * item id. When {@code closeOnPick} is true the picker closes after the first pick (used for
	 * replacing a single slot); otherwise it stays open for adding several items in a row.
	 */
	static void open(Component parent, ItemIndex itemIndex, IntConsumer onPick, boolean closeOnPick)
	{
		final Window owner = SwingUtilities.getWindowAncestor(parent);
		final JDialog dialog = new JDialog(owner, closeOnPick ? "Replace item" : "Add item", Dialog.ModalityType.MODELESS);
		dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);

		// When replacing, dispose the picker after the chosen item is handed off.
		final IntConsumer pick = closeOnPick ? id ->
		{
			onPick.accept(id);
			dialog.dispose();
		} : onPick;

		final JPanel root = new JPanel(new BorderLayout(0, 6));
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);
		root.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		root.setPreferredSize(new Dimension(260, 360));

		final SearchBar field = new SearchBar();
		field.setPreferredSize(new Dimension(100, 30));

		final JPanel results = new ResultsPanel();
		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JScrollPane scroll = new JScrollPane(results,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.getVerticalScrollBar().setUnitIncrement(16);

		final Runnable doSearch = () -> populate(itemIndex, field.getText(), results, scroll, pick);
		field.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyReleased(KeyEvent e)
			{
				doSearch.run();
			}
		});
		field.addClearListener(doSearch);

		root.add(field, BorderLayout.NORTH);
		root.add(scroll, BorderLayout.CENTER);

		final JLabel hint = new JLabel(closeOnPick
			? "Type a name, then click an item to replace this slot."
			: "Type a name, then click an item to add it.");
		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		root.add(hint, BorderLayout.SOUTH);

		dialog.setContentPane(root);
		dialog.pack();
		dialog.setLocationRelativeTo(owner);
		dialog.setVisible(true);
		field.requestFocusInWindow();

		// Kick off the (lazy, one-time) item index build and refresh results once it's ready.
		itemIndex.ensureBuilt(doSearch);
	}

	private static void populate(ItemIndex itemIndex, String query, JPanel results, JScrollPane scroll, IntConsumer onPick)
	{
		results.removeAll();
		final String q = query == null ? "" : query.trim();
		if (q.length() >= 1)
		{
			if (!itemIndex.isReady())
			{
				results.add(message("Loading items..."));
			}
			else
			{
				final List<ItemIndex.Entry> matches = itemIndex.search(q, MAX_RESULTS);
				if (matches.isEmpty())
				{
					results.add(message("No items found."));
				}
				else
				{
					for (ItemIndex.Entry e : matches)
					{
						results.add(resultRow(itemIndex, e.getId(), e.getName(), onPick));
					}
				}
			}
		}
		results.revalidate();
		results.repaint();
		scroll.getVerticalScrollBar().setValue(0);
	}

	private static JButton resultRow(ItemIndex itemIndex, int id, String name, IntConsumer onPick)
	{
		final JButton row = new JButton(name);
		row.setHorizontalAlignment(JButton.LEFT);
		row.setFocusPainted(false);
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setForeground(Color.WHITE);
		row.setBorder(BorderFactory.createEmptyBorder(3, 4, 3, 4));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		row.setToolTipText(name);

		final AsyncBufferedImage img = itemIndex.getImage(id);
		if (img != null)
		{
			img.addTo(row);
		}
		row.addActionListener(e -> onPick.accept(id));
		return row;
	}

	// Results list that fills the scroll viewport when its content is shorter than the viewport, so a short
	// result set (e.g. a couple of matches) doesn't leave a tall, scrollable empty region below it. When the
	// content is taller than the viewport it scrolls normally. Also tracks the viewport width so rows fill it.
	private static final class ResultsPanel extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return getParent() instanceof JViewport && getParent().getHeight() > getPreferredSize().height;
		}
	}

	private static JLabel message(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(BorderFactory.createEmptyBorder(8, 4, 8, 4));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}
}

